const r = await tools.update_plan({
  explanation: "The cached hosted workflow is authoritative for this run. It requires a detached local implementation and verification first, then a Linear completion update and an explicit publication approval gate before any branch, commit, push, or PR.",
  plan: [
    { step: "Resolve cached Skillplane workflow and read the complete MCP-2 Linear record, documents, comments, project, and linked issues", status: "completed" },
    { step: "Fetch latest origin/dev, create a clean detached MCP-2 worktree, and inventory current McpFn and overlapping client/OAuth code", status: "in_progress" },
    { step: "Implement MCP-2 package, client/session, auth, testing, CLI, inspector, migration, and documentation scope locally", status: "pending" },
    { step: "Run focused and release-level local verification, including packed-package and regression gates", status: "pending" },
    { step: "Create or update the canonical MCP-2 Linear completion comment and request publication approval", status: "pending" },
    { step: "After explicit approval only: create exact MCP-2 branch, commit, push, open a PR into dev, and update the canonical Linear comment", status: "pending" }
  ]
});
text(r);

const r = await tools.exec_command({
  cmd: "git fetch origin dev && git rev-parse --verify origin/dev && git log -1 --format='%H%n%ad%n%s' --date=iso-strict origin/dev && git branch --list MCP-2 && git branch -r --list origin/MCP-2 && git worktree list --porcelain && test ! -e /Users/serro/Documents/dev/n/worktrees/superfunctions/MCP-2",
  workdir: "/Users/serro/Documents/dev/n/superfunctions-dev",
  yield_time_ms: 30000,
  max_output_tokens: 20000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "git worktree add --detach /Users/serro/Documents/dev/n/worktrees/superfunctions/MCP-2 origin/dev && git status --short --branch && git rev-parse HEAD && rg --files -g 'AGENTS.md' -g '!node_modules' && find mcpfn -maxdepth 3 -type f | sort | sed -n '1,420p'",
  workdir: "/Users/serro/Documents/dev/n/superfunctions-dev",
  yield_time_ms: 30000,
  max_output_tokens: 40000
});
text(r.output);

const root = "/Users/serro/Documents/dev/n/worktrees/superfunctions/MCP-2";
const cmds = [
  ["STATUS", "git status --short --branch && git rev-parse HEAD && sed -n '1,260p' package.json && sed -n '1,220p' turbo.json"],
  ["MCPFN DOCS", "sed -n '1,320p' mcpfn/ARCHITECTURE.md && sed -n '1,320p' mcpfn/MIGRATION.md && sed -n '1,320p' mcpfn/README.md && sed -n '1,320p' mcpfn/TESTING.md"],
  ["PACKAGES", "for f in mcpfn/*/package.json; do echo \"FILE $f\"; sed -n '1,240p' \"$f\"; done"],
  ["OVERLAP FILES", "rg --files langfn authfn packages superconsole | rg -i '(mcp|oauth|pkce|token|vault|client|transport|redact|inspector)' | sed -n '1,700p'"],
  ["MCPFN SYMBOLS", "rg -n \"export |class |interface |type |function |TODO|FIXME\" mcpfn/*/src mcpfn/*/tests mcpfn/testing/playwright | sed -n '1,1200p'"]
];
const rs = await Promise.all(cmds.map(([label, cmd]) => tools.exec_command({
  cmd,
  workdir: root,
  yield_time_ms: 10000,
  max_output_tokens: 40000
})));
rs.forEach((r, i) => text(`${cmds[i][0]}\n${r.output}`));

