      resource,
      authorizationServers: ["https://login.example.com"],
      requiredScopes: ["mcp:read"],
      verifier: { verifyAccessToken: verifier },
      clock: () => 1_000_000,
    });
    const request = (token?: string) => new Request(resource, {
      method: "POST",
      headers: token ? { authorization: `Bearer ${token}` } : {},
      body: "{}",
    });

