      await this.emit("authorization-request", "failed", readCode(error), {
        redirectOrigin: new URL(requested).origin,
        message: error instanceof Error ? error.message : String(error),
      });
      throw error;
    }
    await this.options.openAuthorization(authorizationUrl);
  }

  saveCodeVerifier(value: string): Promise<void> {
    return this.store.setCodeVerifier(value);
  }

  async codeVerifier(): Promise<string> {
    const value = await this.store.getCodeVerifier();
    if (!value) throw new Error("No PKCE verifier is available for this MCP authorization session");
    return value;
  }

  invalidateCredentials(scope: McpFnOAuthCredentialScope): Promise<void> {
    return this.store.clear(scope);
  }

  async revoke(): Promise<void> {
    const tokens = await this.store.getTokens();
    if (!tokens) return;
    await this.emit("token-revocation", "started");
    try {
      await this.options.revoke?.(tokens);
      await this.store.clear("tokens");
      await this.emit("token-revocation", "succeeded");
    } catch (error) {
      await this.emit("token-revocation", "failed", readCode(error), {
        message: error instanceof Error ? error.message : String(error),
      });
      throw error;
    }
  }

  private async emit(
    phase: McpFnOAuthClientPhase,
    outcome: McpFnOAuthClientDiagnostic["outcome"],
    code?: string,
    details?: Record<string, unknown>,
  ): Promise<void> {
    await this.options.diagnostics?.(redactOAuthValue({
      phase,
      outcome,
      ...(code ? { code } : {}),
      at: (this.options.clock?.() ?? new Date()).toISOString(),
      ...(details ? { details } : {}),
    }));
  }
}

export function createMcpFnOAuthClientProvider(
  options: McpFnOAuthClientProviderOptions,
): McpFnOAuthClientProvider {
  return new McpFnOAuthClientProvider(options);
}

function readCode(error: unknown): string | undefined {
  if (!error || typeof error !== "object") return undefined;
  const value = (error as { code?: unknown }).code;
  return typeof value === "string" || typeof value === "number" ? String(value) : undefined;
}

import type { AuthInfo } from "@modelcontextprotocol/sdk/server/auth/types.js";
import type { HandleRequestOptions } from "@modelcontextprotocol/sdk/server/webStandardStreamableHttp.js";
import type { AuthProvider, AuthSession } from "@superfunctions/auth";

import type { McpFnWebStandardHandler } from "./resource-server.js";

export interface McpFnPrincipal {
  subject: string;
  clientId: string;
  scopes: string[];
  resourceIds: string[];
  expiresAt?: number;
  tenantId?: string;
  regionId?: string;
  authMethods?: string[];
  extra?: Record<string, unknown>;
}

export interface McpFnAuthProviderAdapterOptions<TSession extends AuthSession> {
  provider: AuthProvider<TSession>;
  resource: string | URL;
  map?(session: TSession, request: Request): McpFnPrincipal | Promise<McpFnPrincipal>;
  authorize?(input: {
    principal: McpFnPrincipal;
    request: Request;
  }): boolean | Promise<boolean>;
}

export interface McpFnAuthProviderAdapter<TSession extends AuthSession> {
  authenticate(request: Request): Promise<{
    session: TSession;
    principal: McpFnPrincipal;
    authInfo: AuthInfo;
  } | null>;
}

export function createMcpFnAuthProviderAdapter<TSession extends AuthSession>(
  options: McpFnAuthProviderAdapterOptions<TSession>,
): McpFnAuthProviderAdapter<TSession> {
  const resource = new URL(options.resource.toString());
  resource.hash = "";
  return {
    async authenticate(request) {
      const session = await options.provider.authenticate(request);
      if (!session) return null;
      const principal = options.map
        ? await options.map(session, request)
        : defaultPrincipal(session);
      if (options.authorize && !(await options.authorize({ principal, request }))) {
        return null;
      }
      const bearer = /^Bearer\s+(.+)$/i.exec(
        request.headers.get("authorization")?.trim() ?? "",
      )?.[1] ?? "";
      return {
        session,
        principal,
        authInfo: {
          token: bearer,
          clientId: principal.clientId,
          scopes: [...principal.scopes],
          ...(principal.expiresAt ? { expiresAt: principal.expiresAt } : {}),
          resource,
          extra: {
            subject: principal.subject,
            resourceIds: [...principal.resourceIds],
            ...(principal.tenantId ? { tenantId: principal.tenantId } : {}),
            ...(principal.regionId ? { regionId: principal.regionId } : {}),
            ...(principal.authMethods ? { authMethods: [...principal.authMethods] } : {}),
            ...principal.extra,
          },
        },
      };
    },
  };
}

export function createAuthProviderMcpHandler<TSession extends AuthSession>(
  mcpHandler: McpFnWebStandardHandler,
  options: McpFnAuthProviderAdapterOptions<TSession>,
): (request: Request) => Promise<Response> {
  const adapter = createMcpFnAuthProviderAdapter(options);
  return async (request) => {
    const authenticated = await adapter.authenticate(request.clone());
    if (!authenticated) {
      return Response.json(
        { error: "invalid_token", error_description: "Authentication failed" },
        { status: 401, headers: { "cache-control": "no-store" } },
      );
    }
    const handleOptions: HandleRequestOptions = { authInfo: authenticated.authInfo };
    return mcpHandler(request, handleOptions);
  };
}

function defaultPrincipal(session: AuthSession): McpFnPrincipal {
  return {
    subject: session.subject.actorId,
    clientId: session.id,
    scopes: [...(session.scopes ?? [])],
    resourceIds: [...(session.resourceIds ?? [])],
    ...(session.expiresAt
      ? { expiresAt: Math.floor(session.expiresAt.getTime() / 1_000) }
      : {}),
    ...(session.subject.tenantId ? { tenantId: session.subject.tenantId } : {}),
    ...(session.subject.regionId ? { regionId: session.subject.regionId } : {}),
    ...(session.methods ? { authMethods: [...session.methods] } : {}),
  };
}

