      } catch (error) {
        lastError = error;
        if (error instanceof UnauthorizedError) {
          this._state = "authorization-required";
          await this.emit(
            "authorization-request",
            "succeeded",
            requestId,
            "MCPFN_AUTHORIZATION_REQUIRED",
