  async reconnect(): Promise<void> {
    await this.close(false);
    this._state = "idle";
    await this.connect();
  }

  async terminateSession(): Promise<void> {
    await this.handle?.terminateSession?.();
  }

  async close(permanent = true): Promise<void> {
