export * from "./auth-core.js";
export * from "./mock-oauth-server.js";
import { describe, expect, it } from "vitest";

import { createOAuthResourceServerHandler, protectedResourceMetadataUrl } from "@mcpfn/auth";
import type { AuthInfo } from "@modelcontextprotocol/sdk/server/auth/types.js";

import {
  apiKeyCredential,
  assertAuthRegressionSuite,
  assertAuthorizationCodeClientMetadata,
  assertBearerResourceChallenge,
  bearerCredential,
  createOAuthClientMetadataVariants,
  type McpFnAuthCredential,
} from "../src/auth.js";

describe("McpFn authentication regression suite", () => {
  it("covers OAuth rejection, scope, expiry, audience, revocation, and trusted success", async () => {
    const now = 2_000_000;
    const resource = "https://mcp.example.com/mcp";
    const records = new Map<string, AuthInfo & { revoked?: boolean }>();
    let sequence = 0;
    const verifier = {
      async verifyAccessToken(token: string): Promise<AuthInfo> {
        const record = records.get(token);
        if (!record || record.revoked) throw new Error("invalid token");
        return record;
      },
    };
    const handler = createOAuthResourceServerHandler(
      async (_request, options) => Response.json({ clientId: options?.authInfo?.clientId }),
      {
        resource,
        authorizationServers: ["https://login.example.com"],
        requiredScopes: ["mcp:read"],
        verifier,
        clock: () => now,
      },
    );
    const results = await assertAuthRegressionSuite({
      kind: "oauth",
      resource,
      wrongResource: "https://other.example.com/mcp",
      requiredScopes: ["mcp:read"],
      protectedResourceMetadataUrl: protectedResourceMetadataUrl(resource).toString(),
      provider: {
        capabilities: {
          expiration: true,
          resourceBinding: true,
          revocation: true,
          scopes: true,
        },
        async issue(input) {
          const token = `token-${++sequence}`;
          records.set(token, {
            token,
            clientId: "skillplane-test-client",
            scopes: input.scopes ?? [],
            expiresAt: Math.floor(now / 1_000) + (input.expiresInSeconds ?? 300),
            ...(input.resource ? { resource: new URL(input.resource) } : {}),
          });
          return bearerCredential(token);
        },
        async revoke(credential) {
          const token = new Headers(credential.headers)
            .get("authorization")?.replace(/^Bearer\s+/i, "");
          const record = token ? records.get(token) : undefined;
          if (record) record.revoked = true;
        },
      },
      target: {
        request: (headers) => handler(new Request(resource, {
          method: "POST",
          headers,
          body: "{}",
        })),
      },
      async verifyAuthenticatedResponse(response) {
        await expect(response.json()).resolves.toEqual({
          clientId: "skillplane-test-client",
        });
      },
    });

    expect(results).toHaveLength(8);
    expect(results.every((result) => result.status === "passed")).toBe(true);
  });

  it("covers custom-header API keys without imposing OAuth challenge semantics", async () => {
    const active = new Set<string>();
    let sequence = 0;
    const provider = {
      capabilities: { revocation: true },
      async issue(): Promise<McpFnAuthCredential> {
        const key = `spk_test_${++sequence}`;
        active.add(key);
        return apiKeyCredential(key, { headerName: "x-api-key", scheme: "" });
      },
      async revoke(credential: McpFnAuthCredential): Promise<void> {
        const key = new Headers(credential.headers).get("x-api-key");
        if (key) active.delete(key);
      },
    };
    const results = await assertAuthRegressionSuite({
      kind: "api-key",
      provider,
      invalidCredentialHeaders: { "x-api-key": "not-a-real-key" },
      target: {
        async request(headers) {
          const key = headers.get("x-api-key");
          return new Response(null, { status: key && active.has(key) ? 204 : 401 });
        },
      },
    });
    expect(results.map((result) => result.name)).toEqual([
      "missing-credential",
      "invalid-credential",
      "valid-credential",
      "revoked-credential",
    ]);
  });

  it("accepts authorization-code clients that advertise unrelated extension grants", () => {
    const variants = createOAuthClientMetadataVariants("https://client.example.com");
    for (const metadata of Object.values(variants)) {
      expect(() => assertAuthorizationCodeClientMetadata(metadata, metadata.client_id))
        .not.toThrow();
    }
    expect(variants.jwtBearerExtension.grant_types).toContain(
      "urn:ietf:params:oauth:grant-type:jwt-bearer",
    );
    expect(variants.deviceCodeExtension.grant_types).toContain(
      "urn:ietf:params:oauth:grant-type:device_code",
    );
  });

  it("selects Bearer from multiple challenges and rejects malformed metadata URLs", () => {
    const response = new Response(null, {
      status: 401,
      headers: {
        "www-authenticate": 'Basic realm="legacy", Bearer resource_metadata="https://mcp.example.com/.well-known/oauth-protected-resource"',
      },
    });
    expect(assertBearerResourceChallenge(response).parameters.resource_metadata)
      .toBe("https://mcp.example.com/.well-known/oauth-protected-resource");
    expect(() => assertBearerResourceChallenge(new Response(null, {
      status: 401,
      headers: { "www-authenticate": 'Bearer resource_metadata="not-a-url"' },
    }))).toThrow(/invalid resource_metadata URL/);
  });
});
import { createManifest, type CreateManifestOptions } from "./manifest.js";
import { McpFnRegistry } from "./registry.js";
import {
  createMcpFnServer,
  type McpFnServer,
  type McpFnServerOptions,
} from "./server.js";
import type {
  McpFnManifest,
  McpFnPromptDefinition,
  McpFnResourceDefinition,
  McpFnResourceTemplateDefinition,
  McpFnServerInfo,
  McpFnToolDefinition,
} from "./types.js";

export interface McpFnServerDeclarationOptions<TContext = undefined>
  extends CreateManifestOptions {
  info: McpFnServerInfo;
  tools?: McpFnToolDefinition<TContext>[];
  resources?: McpFnResourceDefinition<TContext>[];
  resourceTemplates?: McpFnResourceTemplateDefinition<TContext>[];
  prompts?: McpFnPromptDefinition<TContext>[];
  /** Reuse an existing registry while adopting the declaration/runtime split. */
  registry?: McpFnRegistry<TContext>;
}

export type McpFnServerRuntimeOptions<TContext> = Omit<
  McpFnServerOptions<TContext>,
  "info" | "registry" | keyof CreateManifestOptions
>;

/**
 * Side-effect-free application declaration. The same registry and manifest
 * feed production transports, deterministic tests, and release tooling.
 */
export class McpFnServerDeclaration<TContext = undefined> {
  readonly info: McpFnServerInfo;
  readonly registry: McpFnRegistry<TContext>;
  private readonly manifestOptions: CreateManifestOptions;

  constructor(options: McpFnServerDeclarationOptions<TContext>) {
    this.info = options.info;
    this.registry = options.registry ?? new McpFnRegistry<TContext>();
    for (const tool of options.tools ?? []) this.registry.register(tool);
    for (const resource of options.resources ?? []) this.registry.registerResource(resource);
    for (const template of options.resourceTemplates ?? []) {
      this.registry.registerResourceTemplate(template);
    }
    for (const prompt of options.prompts ?? []) this.registry.registerPrompt(prompt);
    this.manifestOptions = {
      protocolVersions: options.protocolVersions,
      transports: options.transports,
      extensions: options.extensions,
      capabilities: options.capabilities,
      clientRequirements: options.clientRequirements,
    };
  }

  manifest(): McpFnManifest {
    return createManifest(this.info, this.registry, this.manifestOptions);
  }

  createServer(
    runtime: McpFnServerRuntimeOptions<TContext> = {},
  ): McpFnServer<TContext> {
    return createMcpFnServer({
      ...this.manifestOptions,
      ...runtime,
      info: this.info,
      registry: this.registry,
    });
  }
}

export function defineMcpFnServer<TContext = undefined>(
  options: McpFnServerDeclarationOptions<TContext>,
): McpFnServerDeclaration<TContext> {
  return new McpFnServerDeclaration(options);
}

import { describe, expect, it } from "vitest";
import { InMemoryTransport } from "@modelcontextprotocol/sdk/inMemory.js";
import { McpFnRegistry, createMcpFnServer, structuredResult } from "@mcpfn/core";

import { createMcpFnClient, customTarget } from "../src/index.js";

describe("McpFn production client", () => {
  it("shares the official session engine and paginates complete inventories", async () => {
    const registry = new McpFnRegistry()
      .register({
        name: "one",
        description: "One.",
        inputSchema: { type: "object", additionalProperties: false },
        handler: async () => structuredResult({ value: 1 }),
      })
      .register({
        name: "two",
        description: "Two.",
        inputSchema: { type: "object", additionalProperties: false },
        handler: async () => structuredResult({ value: 2 }),
      });
    const server = createMcpFnServer({
      info: { name: "client-test", version: "1.0.0" },
      registry,
      pageSize: 1,
    });
    const events: Array<{ phase: string; details?: Record<string, unknown> }> = [];
    const client = createMcpFnClient({
      target: customTarget({
        kind: "in-memory",
        open: async () => {
          const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair();
          await server.connect(serverTransport);
          return { transport: clientTransport, close: () => server.close() };
        },
      }),
      diagnostics: (event) => events.push(event),
    });

    await client.connect();
    await expect(client.tools.listAll()).resolves.toHaveLength(2);
    await expect(client.tools.call("two")).resolves.toMatchObject({
      structuredContent: { value: 2 },
    });
    expect(client.getServerVersion()).toMatchObject({ name: "client-test" });
    expect(events).toEqual(expect.arrayContaining([
      expect.objectContaining({ phase: "mcp-initialize" }),
      expect.objectContaining({
        phase: "capability-operation",
        details: expect.objectContaining({ operation: "tools/call" }),
      }),
    ]));
    await client.close();
  });

  it("redacts target queries before diagnostics are emitted", async () => {
    const events: unknown[] = [];
    const client = createMcpFnClient({
      target: customTarget({
        kind: "broken",
        descriptor: { url: "https://example.com/mcp?access_token=secret" },
        open: () => { throw new Error("unavailable"); },
      }),
      diagnostics: (event) => events.push(event),
    });
    await expect(client.connect()).rejects.toMatchObject({
      code: "MCPFN_TARGET_OPEN_FAILED",
    });
    expect(JSON.stringify(events)).not.toContain("secret");
    expect(JSON.stringify(events)).toContain("REDACTED");
  });
});

