import type {
  AddClientAuthentication,
  OAuthClientProvider,
} from "@modelcontextprotocol/sdk/client/auth.js";
import type {
  OAuthClientInformationMixed,
  OAuthClientMetadata,
  OAuthTokens,
} from "@modelcontextprotocol/sdk/shared/auth.js";
import {
  generateStateId,
  redactOAuthValue,
} from "@superfunctions/oauth-core";
import type { TokenCipher } from "@superfunctions/oauth-storage";

import {
  matchMcpRedirectUri,
  type McpFnRedirectPolicy,
} from "./redirects.js";

export type McpFnOAuthCredentialScope = "all" | "client" | "tokens" | "verifier";

export interface McpFnOAuthSessionStore {
  readonly security: "memory" | "encrypted";
  getClientInformation(): Promise<OAuthClientInformationMixed | undefined>;
  setClientInformation(value: OAuthClientInformationMixed): Promise<void>;
  getTokens(): Promise<OAuthTokens | undefined>;
  setTokens(value: OAuthTokens): Promise<void>;
  getCodeVerifier(): Promise<string | undefined>;
  setCodeVerifier(value: string): Promise<void>;
  clear(scope: McpFnOAuthCredentialScope): Promise<void>;
}

export class MemoryMcpFnOAuthSessionStore implements McpFnOAuthSessionStore {
  readonly security = "memory" as const;
  private client?: OAuthClientInformationMixed;
  private tokenSet?: OAuthTokens;
  private verifier?: string;

  async getClientInformation(): Promise<OAuthClientInformationMixed | undefined> {
    return this.client ? structuredClone(this.client) : undefined;
  }

  async setClientInformation(value: OAuthClientInformationMixed): Promise<void> {
    this.client = structuredClone(value);
  }

  async getTokens(): Promise<OAuthTokens | undefined> {
    return this.tokenSet ? structuredClone(this.tokenSet) : undefined;
  }

  async setTokens(value: OAuthTokens): Promise<void> {
    this.tokenSet = structuredClone(value);
  }

  async getCodeVerifier(): Promise<string | undefined> {
    return this.verifier;
  }

  async setCodeVerifier(value: string): Promise<void> {
    this.verifier = value;
  }

  async clear(scope: McpFnOAuthCredentialScope): Promise<void> {
    if (scope === "all" || scope === "client") this.client = undefined;
    if (scope === "all" || scope === "tokens") this.tokenSet = undefined;
    if (scope === "all" || scope === "verifier") this.verifier = undefined;
  }
}

export interface McpFnEncryptedSessionRecord {
  ciphertext: string;
  keyRef: string;
}

export interface McpFnEncryptedSessionRecordStore {
  get(key: string): Promise<McpFnEncryptedSessionRecord | null>;
  put(key: string, value: McpFnEncryptedSessionRecord): Promise<void>;
  delete(key: string): Promise<void>;
}

/** Encrypts client registration, tokens, and the transient verifier at rest. */
export function createEncryptedMcpFnOAuthSessionStore(options: {
  namespace: string;
  keyRef: string;
  cipher: TokenCipher;
  store: McpFnEncryptedSessionRecordStore;
}): McpFnOAuthSessionStore {
  if (!options.namespace || !options.keyRef) {
    throw new Error("Encrypted McpFn OAuth storage requires namespace and keyRef");
  }
  const key = (part: string) => `${options.namespace}:${part}`;
  const get = async <T>(part: string): Promise<T | undefined> => {
    const record = await options.store.get(key(part));
    if (!record) return undefined;
    return JSON.parse(await options.cipher.decrypt(record.ciphertext, record.keyRef)) as T;
  };
  const put = async (part: string, value: unknown): Promise<void> => {
    await options.store.put(key(part), {
      ciphertext: await options.cipher.encrypt(JSON.stringify(value), options.keyRef),
      keyRef: options.keyRef,
    });
  };
  return {
    security: "encrypted",
    getClientInformation: () => get("client"),
    setClientInformation: (value) => put("client", value),
    getTokens: () => get("tokens"),
    setTokens: (value) => put("tokens", value),
    getCodeVerifier: () => get("verifier"),
    setCodeVerifier: (value) => put("verifier", value),
    async clear(scope) {
      if (scope === "all" || scope === "client") await options.store.delete(key("client"));
      if (scope === "all" || scope === "tokens") await options.store.delete(key("tokens"));
      if (scope === "all" || scope === "verifier") await options.store.delete(key("verifier"));
    },
  };
}

export type McpFnOAuthClientPhase =
  | "client-registration"
  | "authorization-request"
  | "token-exchange"
  | "token-refresh"
  | "token-revocation";

export interface McpFnOAuthClientDiagnostic {
  phase: McpFnOAuthClientPhase;
  outcome: "started" | "succeeded" | "failed";
  code?: string;
  at: string;
  details?: Record<string, unknown>;
}

export interface McpFnOAuthClientProviderOptions {
  redirectUrl: string | URL;
  clientMetadata: OAuthClientMetadata;
  clientMetadataUrl?: string;
  store?: McpFnOAuthSessionStore;
  redirectPolicy?: McpFnRedirectPolicy;
  openAuthorization(url: URL): void | Promise<void>;
  diagnostics?(event: McpFnOAuthClientDiagnostic): void | Promise<void>;
  state?: () => string | Promise<string>;
  addClientAuthentication?: AddClientAuthentication;
  validateResourceURL?(serverUrl: string | URL, resource?: string): Promise<URL | undefined>;
  revoke?(tokens: OAuthTokens): void | Promise<void>;
  clock?: () => Date;
}

export class McpFnOAuthClientProvider implements OAuthClientProvider {
  readonly redirectUrl: string | URL;
  readonly clientMetadata: OAuthClientMetadata;
  readonly clientMetadataUrl?: string;
  readonly addClientAuthentication?: AddClientAuthentication;
  readonly validateResourceURL?: McpFnOAuthClientProviderOptions["validateResourceURL"];
  private readonly options: McpFnOAuthClientProviderOptions;
  private readonly store: McpFnOAuthSessionStore;

  constructor(options: McpFnOAuthClientProviderOptions) {
    this.options = options;
    this.redirectUrl = options.redirectUrl;
    this.clientMetadata = structuredClone(options.clientMetadata);
    this.clientMetadataUrl = options.clientMetadataUrl;
    this.store = options.store ?? new MemoryMcpFnOAuthSessionStore();
    this.addClientAuthentication = options.addClientAuthentication;
    this.validateResourceURL = options.validateResourceURL;
    if (!this.clientMetadata.redirect_uris?.length) {
      throw new Error("McpFn OAuth client metadata requires registered redirect_uris");
    }
  }

  state(): string | Promise<string> {
    return this.options.state?.() ?? generateStateId("mcpfn_state");
  }

  clientInformation(): Promise<OAuthClientInformationMixed | undefined> {
    return this.store.getClientInformation();
  }

  async saveClientInformation(value: OAuthClientInformationMixed): Promise<void> {
    await this.emit("client-registration", "succeeded", undefined, {
      clientId: value.client_id,
      storage: this.store.security,
    });
    await this.store.setClientInformation(value);
  }

  tokens(): Promise<OAuthTokens | undefined> {
    return this.store.getTokens();
  }

  async saveTokens(value: OAuthTokens): Promise<void> {
    await this.store.setTokens(value);
    await this.emit("token-exchange", "succeeded", undefined, {
      tokenType: value.token_type,
      hasRefreshToken: Boolean(value.refresh_token),
      storage: this.store.security,
    });
  }

  async redirectToAuthorization(authorizationUrl: URL): Promise<void> {
    await this.emit("authorization-request", "started");
    const requested = authorizationUrl.searchParams.get("redirect_uri");
    if (!requested) {
      await this.emit("authorization-request", "failed", "MCPFN_REDIRECT_MISSING");
      throw new Error("MCP authorization request is missing redirect_uri");
    }
    try {
      const client = await this.store.getClientInformation();
      const registered = "redirect_uris" in (client ?? {}) &&
          Array.isArray((client as { redirect_uris?: unknown }).redirect_uris)
        ? (client as { redirect_uris: string[] }).redirect_uris
        : this.clientMetadata.redirect_uris;
      const match = matchMcpRedirectUri(requested, registered, this.options.redirectPolicy);
      await this.emit("authorization-request", "succeeded", undefined, {
        redirect: match,
        clientId: authorizationUrl.searchParams.get("client_id"),
      });
    } catch (error) {
      await this.emit("authorization-request", "failed", readCode(error), {
        redirectOrigin: new URL(requested).origin,
        message: error instanceof Error ? error.message : String(error),
      });
      throw error;
    }
    await this.options.openAuthorization(authorizationUrl);
  }

  saveCodeVerifier(value: string): Promise<void> {
    return this.store.setCodeVerifier(value);
  }

  async codeVerifier(): Promise<string> {
    const value = await this.store.getCodeVerifier();
    if (!value) throw new Error("No PKCE verifier is available for this MCP authorization session");
    return value;
  }

  invalidateCredentials(scope: McpFnOAuthCredentialScope): Promise<void> {
    return this.store.clear(scope);
  }

  async revoke(): Promise<void> {
    const tokens = await this.store.getTokens();
    if (!tokens) return;
    await this.emit("token-revocation", "started");
    try {
      await this.options.revoke?.(tokens);
      await this.store.clear("tokens");
      await this.emit("token-revocation", "succeeded");
    } catch (error) {
      await this.emit("token-revocation", "failed", readCode(error), {
        message: error instanceof Error ? error.message : String(error),
      });
      throw error;
    }
  }

  private async emit(
    phase: McpFnOAuthClientPhase,
    outcome: McpFnOAuthClientDiagnostic["outcome"],
    code?: string,
    details?: Record<string, unknown>,
  ): Promise<void> {
    await this.options.diagnostics?.(redactOAuthValue({
      phase,
      outcome,
      ...(code ? { code } : {}),
      at: (this.options.clock?.() ?? new Date()).toISOString(),
      ...(details ? { details } : {}),
    }));
  }
}

export function createMcpFnOAuthClientProvider(
  options: McpFnOAuthClientProviderOptions,
): McpFnOAuthClientProvider {
  return new McpFnOAuthClientProvider(options);
}

function readCode(error: unknown): string | undefined {
  if (!error || typeof error !== "object") return undefined;
  const value = (error as { code?: unknown }).code;
  return typeof value === "string" || typeof value === "number" ? String(value) : undefined;
}

import type { OAuthClientMetadata } from "@modelcontextprotocol/sdk/shared/auth.js";
import { redactOAuthValue } from "@superfunctions/oauth-core";

import {
  matchMcpRedirectUri,
  McpFnRedirectMismatchError,
  type McpFnRedirectPolicy,
} from "./redirects.js";

export type McpFnClientRegistrationSource =
  | "pre-registered"
  | "dynamic"
  | "client-metadata-document"
  | "enterprise";

export interface McpFnNormalizedClientRegistration {
  clientId: string;
  source: McpFnClientRegistrationSource;
  redirectUris: string[];
  responseTypes: string[];
  grantTypes: string[];
  tokenEndpointAuthMethod: string;
  metadata: OAuthClientMetadata;
}

export interface McpFnHostedClientRegistry {
  resolve(clientId: string): Promise<McpFnNormalizedClientRegistration | null>;
  register?(
    metadata: OAuthClientMetadata,
    request: Request,
  ): Promise<McpFnNormalizedClientRegistration>;
}

export interface McpFnValidatedAuthorizationRequest {
  client: McpFnNormalizedClientRegistration;
  responseType: "code";
  redirectUri: string;
  redirectMatch: "exact" | "loopback-dynamic-port";
  codeChallenge: string;
  codeChallengeMethod: "S256";
  scopes: string[];
  state?: string;
  resource?: string;
  raw: URLSearchParams;
}

export class McpFnHostedAuthorizationError extends Error {
  readonly code: string;
  readonly status: number;
  readonly details?: Record<string, unknown>;

  constructor(
    code: string,
    message: string,
    options: { status?: number; details?: Record<string, unknown> } = {},
  ) {
    super(message);
    this.name = "McpFnHostedAuthorizationError";
    this.code = code;
    this.status = options.status ?? 400;
    this.details = options.details;
  }
}

export function normalizeMcpClientRegistration(input: {
  clientId: string;
  source: McpFnClientRegistrationSource;
  metadata: OAuthClientMetadata;
}): McpFnNormalizedClientRegistration {
  if (!input.clientId) {
    throw new McpFnHostedAuthorizationError("invalid_client_metadata", "client_id is required");
  }
  const redirectUris = uniqueUrls(input.metadata.redirect_uris ?? []);
  if (!redirectUris.length) {
    throw new McpFnHostedAuthorizationError(
      "invalid_client_metadata",
      "At least one redirect_uri is required",
    );
  }
  const responseTypes = unique(input.metadata.response_types ?? ["code"]);
  const grantTypes = unique(input.metadata.grant_types ?? ["authorization_code"]);
  return {
    clientId: input.clientId,
    source: input.source,
    redirectUris,
    responseTypes,
    grantTypes,
    tokenEndpointAuthMethod: input.metadata.token_endpoint_auth_method ?? "none",
    metadata: {
      ...input.metadata,
      redirect_uris: redirectUris,
      response_types: responseTypes,
      grant_types: grantTypes,
      token_endpoint_auth_method: input.metadata.token_endpoint_auth_method ?? "none",
    },
  };
}

export function validateMcpAuthorizationRequest(options: {
  url: string | URL;
  client: McpFnNormalizedClientRegistration;
  redirectPolicy?: McpFnRedirectPolicy;
  allowedResources?: ReadonlyArray<string | URL>;
  supportedScopes?: ReadonlyArray<string>;
}): McpFnValidatedAuthorizationRequest {
  const url = new URL(options.url.toString());
  const responseType = url.searchParams.get("response_type");
  if (responseType !== "code" || !options.client.responseTypes.includes("code")) {
    throw new McpFnHostedAuthorizationError(
      "unsupported_response_type",
      "This MCP authorization profile requires response_type=code",
    );
  }
  if (!options.client.grantTypes.includes("authorization_code")) {
    throw new McpFnHostedAuthorizationError(
      "unauthorized_client",
      "The client has no compatible authorization_code flow",
    );
  }
  const requestedClientId = url.searchParams.get("client_id");
  if (requestedClientId !== options.client.clientId) {
    throw new McpFnHostedAuthorizationError("invalid_client", "client_id does not match registration");
  }
  const redirectUri = url.searchParams.get("redirect_uri");
  if (!redirectUri) {
    throw new McpFnHostedAuthorizationError("invalid_request", "redirect_uri is required");
  }
  let redirectMatch;
  try {
    redirectMatch = matchMcpRedirectUri(
      redirectUri,
      options.client.redirectUris,
      options.redirectPolicy,
    );
  } catch (error) {
    if (error instanceof McpFnRedirectMismatchError) {
      throw new McpFnHostedAuthorizationError(
        "invalid_request",
        error.message,
        { details: { phase: "redirect-validation", redirect: error.requested } },
      );
    }
    throw error;
  }
  const codeChallenge = url.searchParams.get("code_challenge");
  if (!codeChallenge) {
    throw new McpFnHostedAuthorizationError("invalid_request", "PKCE code_challenge is required");
  }
  if (url.searchParams.get("code_challenge_method") !== "S256") {
    throw new McpFnHostedAuthorizationError(
      "invalid_request",
      "PKCE code_challenge_method must be S256",
    );
  }
  const resource = url.searchParams.get("resource") ?? undefined;
  if (resource && options.allowedResources?.length) {
    const allowed = new Set(options.allowedResources.map((value) => new URL(value.toString()).toString()));
    if (!allowed.has(new URL(resource).toString())) {
      throw new McpFnHostedAuthorizationError("invalid_target", "resource is not allowed");
    }
  }
  const scopes = unique((url.searchParams.get("scope") ?? "").split(/\s+/).filter(Boolean));
  if (options.supportedScopes) {
    const supported = new Set(options.supportedScopes);
    const unsupported = scopes.filter((scope) => !supported.has(scope));
    if (unsupported.length) {
      throw new McpFnHostedAuthorizationError("invalid_scope", "Requested MCP scope is unsupported", {
        details: { unsupportedScopes: unsupported },
      });
    }
  }
  return {
    client: options.client,
    responseType: "code",
    redirectUri: new URL(redirectUri).toString(),
    redirectMatch: redirectMatch.kind,
    codeChallenge,
    codeChallengeMethod: "S256",
    scopes,
    ...(url.searchParams.get("state") ? { state: url.searchParams.get("state")! } : {}),
    ...(resource ? { resource: new URL(resource).toString() } : {}),
    raw: new URLSearchParams(url.searchParams),
  };
}

export interface McpFnAuthorizationCompatibilityOptions {
  issuer: string | URL;
  clients: McpFnHostedClientRegistry;
  authorize(
    input: McpFnValidatedAuthorizationRequest,
    request: Request,
  ): Promise<Response> | Response;
  token(request: Request): Promise<Response> | Response;
  revoke?(request: Request): Promise<Response> | Response;
  supportedScopes?: string[];
  allowedResources?: Array<string | URL>;
  redirectPolicy?: McpFnRedirectPolicy;
  clientMetadataDocuments?: {
    enabled: boolean;
    fetch?: typeof globalThis.fetch;
    maxBytes?: number;
  };
  extraMetadata?: Record<string, unknown>;
  diagnostics?(event: {
    phase: string;
    outcome: "succeeded" | "failed";
    code?: string;
    details?: Record<string, unknown>;
  }): void | Promise<void>;
}

/**
 * MCP-specific authorization compatibility router. Identity, login, consent,
 * signing, token issuance, and durable security state stay in the callbacks.
 */
export function createMcpAuthorizationCompatibilityHandler(
  options: McpFnAuthorizationCompatibilityOptions,
): (request: Request) => Promise<Response> {
  const issuer = new URL(options.issuer.toString());
  issuer.hash = "";
  const endpoint = (path: string) => new URL(path, issuer).toString();
  const metadata = {
    ...options.extraMetadata,
    issuer: issuer.toString(),
    authorization_endpoint: endpoint("/authorize"),
    token_endpoint: endpoint("/token"),
    ...(options.clients.register ? { registration_endpoint: endpoint("/register") } : {}),
    ...(options.revoke ? { revocation_endpoint: endpoint("/revoke") } : {}),
    response_types_supported: ["code"],
    grant_types_supported: ["authorization_code", "refresh_token"],
    code_challenge_methods_supported: ["S256"],
    token_endpoint_auth_methods_supported: ["none", "client_secret_basic", "client_secret_post"],
    ...(options.supportedScopes ? { scopes_supported: unique(options.supportedScopes) } : {}),
    client_id_metadata_document_supported: options.clientMetadataDocuments?.enabled === true,
  };

  return async (request): Promise<Response> => {
    const url = new URL(request.url);
    try {
      if (
        request.method === "GET" &&
        (url.pathname === "/.well-known/oauth-authorization-server" ||
          url.pathname === "/.well-known/openid-configuration")
      ) {
        return json(200, metadata, { "cache-control": "public, max-age=300" });
      }
      if (request.method === "POST" && url.pathname === "/register") {
        if (!options.clients.register) {
          throw new McpFnHostedAuthorizationError(
            "invalid_request",
            "Dynamic client registration is disabled",
            { status: 404 },
          );
        }
        const raw = await readBoundedJson(request, 256_000) as OAuthClientMetadata;
        const metadata = normalizeClientMetadata(raw);
        const registration = await options.clients.register(metadata, request);
        await emit(options, "client-registration", "succeeded", undefined, {
          clientId: registration.clientId,
          source: registration.source,
        });
        return json(201, {
          ...registration.metadata,
          client_id: registration.clientId,
        });
      }
      if (request.method === "GET" && url.pathname === "/authorize") {
        const clientId = url.searchParams.get("client_id");
        if (!clientId) {
          throw new McpFnHostedAuthorizationError("invalid_request", "client_id is required");
        }
        const client = await resolveClient(options, clientId);
        if (!client) {
          throw new McpFnHostedAuthorizationError("invalid_client", "Unknown MCP client");
        }
        const validated = validateMcpAuthorizationRequest({
          url,
          client,
          redirectPolicy: options.redirectPolicy,
          allowedResources: options.allowedResources,
          supportedScopes: options.supportedScopes,
        });
        await emit(options, "authorization-request", "succeeded", undefined, {
          clientId,
          registrationSource: client.source,
          redirectMatch: validated.redirectMatch,
        });
        return options.authorize(validated, request);
      }
      if (request.method === "POST" && url.pathname === "/token") {
        return options.token(request);
      }
      if (request.method === "POST" && url.pathname === "/revoke" && options.revoke) {
        return options.revoke(request);
      }
      return json(404, { error: "not_found" });
    } catch (error) {
      const normalized = error instanceof McpFnHostedAuthorizationError
        ? error
        : new McpFnHostedAuthorizationError(
          "server_error",
          "MCP authorization compatibility processing failed",
          { status: 500 },
        );
      await emit(options, inferPhase(url.pathname), "failed", normalized.code, {
        message: normalized.message,
        ...normalized.details,
      });
      return json(normalized.status, {
        error: normalized.code,
        error_description: normalized.message,
      });
    }
  };
}

async function resolveClient(
  options: McpFnAuthorizationCompatibilityOptions,
  clientId: string,
): Promise<McpFnNormalizedClientRegistration | null> {
  const stored = await options.clients.resolve(clientId);
  if (stored) return stored;
  if (!options.clientMetadataDocuments?.enabled) return null;
  let clientUrl: URL;
  try {
    clientUrl = new URL(clientId);
  } catch {
    return null;
  }
  if (clientUrl.protocol !== "https:" || clientUrl.pathname === "/") return null;
  const fetchImplementation = options.clientMetadataDocuments.fetch ?? globalThis.fetch;
  if (!fetchImplementation) throw new Error("A fetch implementation is required");
  const response = await fetchImplementation(clientUrl, {
    headers: { accept: "application/json" },
  });
  if (!response.ok) {
    await response.body?.cancel();
    throw new McpFnHostedAuthorizationError(
      "invalid_client",
      "Client ID Metadata Document could not be loaded",
    );
  }
  const raw = await readBoundedJson(response, options.clientMetadataDocuments.maxBytes ?? 256_000);
  const record = raw as Record<string, unknown>;
  if (record.client_id !== undefined && record.client_id !== clientId) {
    throw new McpFnHostedAuthorizationError(
      "invalid_client_metadata",
      "Client ID Metadata Document client_id does not match its URL",
    );
  }
  return normalizeMcpClientRegistration({
    clientId,
    source: "client-metadata-document",
    metadata: normalizeClientMetadata(record as OAuthClientMetadata),
  });
}

function normalizeClientMetadata(value: OAuthClientMetadata): OAuthClientMetadata {
  if (!value || typeof value !== "object") {
    throw new McpFnHostedAuthorizationError("invalid_client_metadata", "Client metadata must be an object");
  }
  return {
    ...value,
    redirect_uris: Array.isArray(value.redirect_uris) ? value.redirect_uris : [],
  };
}

async function readBoundedJson(
  source: Request | Response,
  maxBytes: number,
): Promise<unknown> {
  const length = Number(source.headers.get("content-length") ?? "0");
  if (Number.isFinite(length) && length > maxBytes) {
    throw new McpFnHostedAuthorizationError("invalid_request", "Metadata body is too large", {
      status: 413,
    });
  }
  const text = await source.text();
  if (new TextEncoder().encode(text).byteLength > maxBytes) {
    throw new McpFnHostedAuthorizationError("invalid_request", "Metadata body is too large", {
      status: 413,
    });
  }
  try {
    return JSON.parse(text);
  } catch {
    throw new McpFnHostedAuthorizationError("invalid_request", "Metadata body is not valid JSON");
  }
}

function json(status: number, body: unknown, headers: HeadersInit = {}): Response {
  return Response.json(body, {
    status,
    headers: {
      "cache-control": "no-store",
      ...Object.fromEntries(new Headers(headers)),
    },
  });
}

function unique(values: string[]): string[] {
  return [...new Set(values)].sort();
}

function uniqueUrls(values: Array<string | URL>): string[] {
  return unique(values.map((value) => new URL(value.toString()).toString()));
}

async function emit(
  options: McpFnAuthorizationCompatibilityOptions,
  phase: string,
  outcome: "succeeded" | "failed",
  code?: string,
  details?: Record<string, unknown>,
): Promise<void> {
  await options.diagnostics?.(redactOAuthValue({
    phase,
    outcome,
    ...(code ? { code } : {}),
    ...(details ? { details } : {}),
import type { AuthInfo } from "@modelcontextprotocol/sdk/server/auth/types.js";
import type { HandleRequestOptions } from "@modelcontextprotocol/sdk/server/webStandardStreamableHttp.js";
import type { AuthProvider, AuthSession } from "@superfunctions/auth";

import type { McpFnWebStandardHandler } from "./resource-server.js";

export interface McpFnPrincipal {
  subject: string;
  clientId: string;
  scopes: string[];
  resourceIds: string[];
  expiresAt?: number;
  tenantId?: string;
  regionId?: string;
  authMethods?: string[];
  extra?: Record<string, unknown>;
}

export interface McpFnAuthProviderAdapterOptions<TSession extends AuthSession> {
  provider: AuthProvider<TSession>;
  resource: string | URL;
  map?(session: TSession, request: Request): McpFnPrincipal | Promise<McpFnPrincipal>;
  authorize?(input: {
    principal: McpFnPrincipal;
    request: Request;
  }): boolean | Promise<boolean>;
}

export interface McpFnAuthProviderAdapter<TSession extends AuthSession> {
  authenticate(request: Request): Promise<{
    session: TSession;
    principal: McpFnPrincipal;
    authInfo: AuthInfo;
  } | null>;
}

export function createMcpFnAuthProviderAdapter<TSession extends AuthSession>(
  options: McpFnAuthProviderAdapterOptions<TSession>,
): McpFnAuthProviderAdapter<TSession> {
  const resource = new URL(options.resource.toString());
  resource.hash = "";
  return {
    async authenticate(request) {
      const session = await options.provider.authenticate(request);
      if (!session) return null;
      const principal = options.map
        ? await options.map(session, request)
        : defaultPrincipal(session);
      if (options.authorize && !(await options.authorize({ principal, request }))) {
        return null;
      }
      const bearer = /^Bearer\s+(.+)$/i.exec(
        request.headers.get("authorization")?.trim() ?? "",
      )?.[1] ?? "";
      return {
        session,
        principal,
        authInfo: {
          token: bearer,
          clientId: principal.clientId,
          scopes: [...principal.scopes],
          ...(principal.expiresAt ? { expiresAt: principal.expiresAt } : {}),
          resource,
          extra: {
            subject: principal.subject,
            resourceIds: [...principal.resourceIds],
            ...(principal.tenantId ? { tenantId: principal.tenantId } : {}),
            ...(principal.regionId ? { regionId: principal.regionId } : {}),
            ...(principal.authMethods ? { authMethods: [...principal.authMethods] } : {}),
            ...principal.extra,
          },
        },
      };
    },
  };
}

export function createAuthProviderMcpHandler<TSession extends AuthSession>(
  mcpHandler: McpFnWebStandardHandler,
  options: McpFnAuthProviderAdapterOptions<TSession>,
): (request: Request) => Promise<Response> {
  const adapter = createMcpFnAuthProviderAdapter(options);
  return async (request) => {
    const authenticated = await adapter.authenticate(request.clone());
    if (!authenticated) {
      return Response.json(
        { error: "invalid_token", error_description: "Authentication failed" },
        { status: 401, headers: { "cache-control": "no-store" } },
      );
    }
    const handleOptions: HandleRequestOptions = { authInfo: authenticated.authInfo };
    return mcpHandler(request, handleOptions);
  };
}

function defaultPrincipal(session: AuthSession): McpFnPrincipal {
  return {
    subject: session.subject.actorId,
    clientId: session.id,
    scopes: [...(session.scopes ?? [])],
    resourceIds: [...(session.resourceIds ?? [])],
    ...(session.expiresAt
      ? { expiresAt: Math.floor(session.expiresAt.getTime() / 1_000) }
      : {}),
    ...(session.subject.tenantId ? { tenantId: session.subject.tenantId } : {}),
    ...(session.subject.regionId ? { regionId: session.subject.regionId } : {}),
    ...(session.methods ? { authMethods: [...session.methods] } : {}),
  };
}

const REDACTED = "[REDACTED]";

const SECRET_KEY = /(?:^|_)(?:access|refresh|id)?_?token$|authorization|bearer|password|secret|client_secret|code_verifier|pkce|session(?:_?id)?|cookie/i;
const SENSITIVE_QUERY_KEY = /^(?:code|state|token|access_token|refresh_token|id_token|client_secret|code_verifier)$/i;

export interface OAuthRedactionOptions {
  maxDepth?: number;
  maxArrayEntries?: number;
  maxStringLength?: number;
}

/**
 * Redacts OAuth/session credentials and bounds diagnostic values before they
 * reach logs, CLI reports, test artifacts, or inspector event streams.
 */
export function redactOAuthValue<T>(
  value: T,
  options: OAuthRedactionOptions = {},
): T {
  return redact(value, {
    maxDepth: options.maxDepth ?? 8,
    maxArrayEntries: options.maxArrayEntries ?? 100,
    maxStringLength: options.maxStringLength ?? 2_048,
  }, 0) as T;
}

function redact(
  value: unknown,
  options: Required<OAuthRedactionOptions>,
  depth: number,
): unknown {
  if (depth > options.maxDepth) return "[TRUNCATED]";
  if (Array.isArray(value)) {
    return value
      .slice(0, options.maxArrayEntries)
      .map((entry) => redact(entry, options, depth + 1));
  }
  if (value && typeof value === "object") {
    if (value instanceof URL) return redactUrl(value, options.maxStringLength);
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>).map(([key, entry]) => [
        key,
        SECRET_KEY.test(key) ? REDACTED : redact(entry, options, depth + 1),
      ]),
    );
  }
  if (typeof value === "string") {
    const redactedUrl = maybeRedactUrl(value, options.maxStringLength);
    if (redactedUrl !== undefined) return redactedUrl;
    return value.length > options.maxStringLength
      ? `${value.slice(0, options.maxStringLength)}…`
      : value;
  }
  return value;
}

function maybeRedactUrl(value: string, maxLength: number): string | undefined {
  if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(value)) return undefined;
  try {
    return redactUrl(new URL(value), maxLength);
  } catch {
    return undefined;
  }
}

function redactUrl(url: URL, maxLength: number): string {
  const copy = new URL(url.toString());
  for (const key of [...copy.searchParams.keys()]) {
    if (SENSITIVE_QUERY_KEY.test(key)) copy.searchParams.set(key, REDACTED);
  }
  copy.username = "";
  copy.password = "";
  const serialized = copy.toString();
  return serialized.length > maxLength
    ? `${serialized.slice(0, maxLength)}…`
    : serialized;
}

