   398	  private async operation<T>(name: string, run: () => Promise<T>): Promise<T> {
   399	    const requestId = this.requestId();
   400	    await this.emit("capability-operation", "started", requestId, undefined, { operation: name });
   401	    try {
   402	      const result = await run();
   403	      await this.emit("capability-operation", "succeeded", requestId, undefined, {
   404	        operation: name,
   405	      });
   406	      return result;
   407	    } catch (error) {
   408	      await this.emit("capability-operation", "failed", requestId, errorCode(error), {
   409	        operation: name,
   410	        message: errorMessage(error),
   411	      });
   412	      throw error;
   413	    }
   414	  }
