   422	    outcome: McpFnDiagnosticEvent["outcome"],
   423	    requestId: string,
   424	    code?: string,
   425	    details?: Record<string, unknown>,
   426	  ): Promise<void> {
   427	    await this.dispatch({
   428	      phase,
   429	      outcome,
   430	      ...(code ? { code } : {}),
   431	      requestId,
   432	      at: (this.options.clock?.() ?? new Date()).toISOString(),
   433	      target: redactOAuthValue(this.options.target.describe()),
   434	      ...(details ? { details: redactOAuthValue(details) } : {}),
   435	    });
