  1	const REDACTED = "[REDACTED]";
  2	
  3	const SECRET_KEY = /(?:^|_)(?:access|refresh|id)?_?token$|authorization(?:_?code)?|bearer|password|secret|client_secret|code_verifier|pkce|state$|session(?:_?id)?|cookie|api_?key|credential/i;
  4	const SENSITIVE_QUERY_KEY = /^(?:code|state|token|access_token|refresh_token|id_token|client_secret|code_verifier)$/i;
  5	
  6	export interface OAuthRedactionOptions {
  7	  maxDepth?: number;
  8	  maxArrayEntries?: number;
  9	  maxStringLength?: number;
 10	}
 11	
 12	/**
 13	 * Redacts OAuth/session credentials and bounds diagnostic values before they
 14	 * reach logs, CLI reports, test artifacts, or inspector event streams.
 15	 */
 16	export function redactOAuthValue<T>(
 17	  value: T,
 18	  options: OAuthRedactionOptions = {},
 19	): T {
 20	  return redact(value, {
 21	    maxDepth: options.maxDepth ?? 8,
 22	    maxArrayEntries: options.maxArrayEntries ?? 100,
 23	    maxStringLength: options.maxStringLength ?? 2_048,
 24	  }, 0) as T;
 25	}
 26	
 27	function redact(
 28	  value: unknown,
 29	  options: Required<OAuthRedactionOptions>,
 30	  depth: number,
 31	): unknown {
 32	  if (depth > options.maxDepth) return "[TRUNCATED]";
 33	  if (Array.isArray(value)) {
 34	    return value
 35	      .slice(0, options.maxArrayEntries)
 36	      .map((entry) => redact(entry, options, depth + 1));
 37	  }
 38	  if (value && typeof value === "object") {
 39	    if (value instanceof URL) return redactUrl(value, options.maxStringLength);
 40	    return Object.fromEntries(
 41	      Object.entries(value as Record<string, unknown>).map(([key, entry]) => [
 42	        key,
 43	        SECRET_KEY.test(key) ? REDACTED : redact(entry, options, depth + 1),
 44	      ]),
 45	    );
 46	  }
 47	  if (typeof value === "string") {
 48	    const redactedUrl = maybeRedactUrl(value, options.maxStringLength);
 49	    if (redactedUrl !== undefined) return redactedUrl;
 50	    return value.length > options.maxStringLength
 51	      ? `${value.slice(0, options.maxStringLength)}…`
 52	      : value;
 53	  }
 54	  return value;
 55	}
 56	
 57	function maybeRedactUrl(value: string, maxLength: number): string | undefined {
 58	  if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(value)) return undefined;
 59	  try {
 60	    return redactUrl(new URL(value), maxLength);
 61	  } catch {
 62	    return undefined;
 63	  }
 64	}
 65	
 66	function redactUrl(url: URL, maxLength: number): string {
 67	  const copy = new URL(url.toString());
 68	  for (const key of [...copy.searchParams.keys()]) {
 69	    if (SENSITIVE_QUERY_KEY.test(key)) copy.searchParams.set(key, REDACTED);
 70	  }
 71	  copy.username = "";
 72	  copy.password = "";
 73	  const serialized = copy.toString();
 74	  return serialized.length > maxLength
 75	    ? `${serialized.slice(0, maxLength)}…`
 76	    : serialized;
 77	}
