    15	export default function createCalculatorServer() {
    16	  const registry = new McpFnRegistry()
    17	    .register({
    18	      name: "calculator_sum",
    19	      description: "Add two finite numbers.",
    20	      inputSchema: {
    21	        type: "object",
    22	        properties: {
    23	          left: { type: "number" },
    24	          right: { type: "number" },
    25	        },
    26	        required: ["left", "right"],
    27	        additionalProperties: false,
    28	      },
    29	      outputSchema: numberResultSchema,
    30	      annotations: {
    31	        readOnlyHint: true,
    32	        destructiveHint: false,
    33	        idempotentHint: true,
    34	        openWorldHint: false,
    35	      },
    36	      handler: async ({ left, right }) =>
    37	        structuredResult({ result: Number(left) + Number(right) }),
    38	    })
    39	    .register({
    40	      name: "calculator_divide",
    41	      description: "Divide one finite number by another non-zero number.",
    42	      inputSchema: {
    43	        type: "object",
    44	        properties: {
    45	          dividend: { type: "number" },
    46	          divisor: { type: "number" },
    47	        },
    48	        required: ["dividend", "divisor"],
    49	        additionalProperties: false,
    50	      },
    51	      outputSchema: numberResultSchema,
    52	      annotations: {
    53	        readOnlyHint: true,
    54	        destructiveHint: false,
    55	        idempotentHint: true,
    56	        openWorldHint: false,
    57	      },
    58	      handler: async ({ dividend, divisor }) => {
    59	        if (divisor === 0) {
    60	          throw new McpFnError(
    61	            "CALCULATOR_DIVIDE_BY_ZERO",
    62	            "The divisor must not be zero.",
    63	          );
    64	        }
    65	        return structuredResult({
    66	          result: Number(dividend) / Number(divisor),
    67	        });
    68	      },
    69	    });
    70	
    71	  return createMcpFnServer({
    72	    info: {
    73	      name: "mcpfn-calculator-example",
    74	      version: "1.0.0",
    75	      instructions: "Use the calculator tools for deterministic arithmetic.",
    76	    },
    77	    registry,
    78	    transports: ["stdio", "streamable-http"],
    79	  });
    80	}
