 32	export function customTarget(options: {
 33	  kind: string;
 34	  descriptor?: Record<string, unknown>;
 35	  open(context: McpFnTargetContext): Promise<McpFnTransportHandle> | McpFnTransportHandle;
 36	}): McpFnTarget {
