 45	export function transportTarget(
 46	  transport: Transport,
 47	  descriptor: McpFnTargetDescriptor = { kind: "custom" },
 48	): McpFnTarget {
 49	  let opened = false;
 50	  return customTarget({
 51	    kind: descriptor.kind,
 52	    descriptor,
 53	    open: () => {
 54	      if (opened) throw new Error("A one-shot McpFn transport target cannot be reopened");
 55	      opened = true;
 56	      return { transport };
 57	    },
 58	  });
