 61	export function stdioTarget(options: McpFnStdioTargetOptions): McpFnTarget {
 62	  if (!options.command.trim()) throw new Error("McpFn stdio target command is required");
 63	  return customTarget({
 64	    kind: "stdio",
 65	    descriptor: {
 66	      command: options.command,
 67	      ...(options.cwd ? { cwd: options.cwd } : {}),
 68	    },
 69	    open: () => {
 70	      const transport = new StdioClientTransport(options);
 71	      return {
 72	        transport,
 73	        close: () => transport.close(),
 74	      };
 75	    },
 76	  });
 77	}
