 79	export function streamableHttpTarget(
 80	  url: string | URL,
 81	  options: McpFnStreamableHttpTargetOptions = {},
 82	): McpFnTarget {
 83	  const targetUrl = new URL(url.toString());
 84	  const descriptorUrl = new URL(targetUrl.toString());
 85	  descriptorUrl.search = "";
 86	  descriptorUrl.hash = "";
 87	  return customTarget({
 88	    kind: "streamable-http",
 89	    descriptor: { url: descriptorUrl.toString() },
 90	    open: () => {
 91	      const transport = new StreamableHTTPClientTransport(targetUrl, options);
 92	      return {
 93	        transport,
 94	        finishAuthorization: async (authorizationCode, state) => {
 95	          await (options.authProvider as StateValidatingOAuthProvider | undefined)
 96	            ?.validateAuthorizationState?.(state);
 97	          await transport.finishAuth(authorizationCode);
 98	        },
 99	        terminateSession: () => transport.terminateSession(),
100	        close: () => transport.close(),
101	      };
102	    },
103	  });
104	}
