      results.push({
        name: scenario.name,
        operation,
        ...(isToolScenario(scenario) ? { tool: scenario.tool } : {}),
        status: "failed",
        durationMs: performance.now() - startedAt,
        error: redactOAuthValue(error instanceof Error ? error.message : String(error)),
      });
    }
  }
  return results;
}

async function executeScenario(
  client: McpFnTestClient<unknown>,
  scenario: McpFnScenario,
): Promise<void> {
  const kind = scenario.kind ?? "tools.call";
  if (kind === "tools.call" && isToolScenario(scenario)) {
    const result = await client.callTool(scenario.tool, scenario.arguments);
    if (result.isError && scenario.expect?.isError === undefined) {
      throw new McpFnAssertionError(
        "Tool returned isError=true without an explicit expect.isError=true assertion",
      );
    }
    if (
      scenario.expect?.isError !== undefined &&
      Boolean(result.isError) !== scenario.expect.isError
    ) {
      throw new McpFnAssertionError(
        `Expected isError=${scenario.expect.isError}, received ${Boolean(result.isError)}`,
      );
    }
    if (
      scenario.expect &&
      Object.prototype.hasOwnProperty.call(scenario.expect, "structuredContent") &&
      stableJson(result.structuredContent) !== stableJson(scenario.expect.structuredContent)
    ) {
      throw new McpFnAssertionError(
        `Structured result mismatch\nexpected: ${stableJson(scenario.expect.structuredContent)}\nactual:   ${stableJson(result.structuredContent)}`,
      );
    }
    if (scenario.expect?.structuredTextParity) assertStructuredTextParity(result);
    await scenario.verify?.(result);
    return;
  }
  if (kind === "initialize" && scenario.kind === "initialize") {
    const actual = client.client.getServerCapabilities() ?? {};
    if (scenario.expectCapabilities && stableJson(actual) !== stableJson(scenario.expectCapabilities)) {
      throw new McpFnAssertionError(
        `Capability mismatch\nexpected: ${stableJson(scenario.expectCapabilities)}\nactual:   ${stableJson(actual)}`,
      );
    }
    return;
  }
  if (isInventoryScenario(scenario)) {
    const values = kind === "tools.list"
      ? await client.listTools()
      : kind === "resources.list"
        ? await client.listResources()
        : kind === "resources.templates.list"
          ? await client.listResourceTemplates()
          : await client.listPrompts();
    if (scenario.expectNames) {
      const actual = values.map((value) => value.name).sort();
      const expected = [...scenario.expectNames].sort();
      if (stableJson(actual) !== stableJson(expected)) {
        throw new McpFnAssertionError(
          `Inventory mismatch\nexpected: ${stableJson(expected)}\nactual:   ${stableJson(actual)}`,
        );
      }
    }
    return;
  }
  if (scenario.kind === "resources.read") {
    assertExpected(await client.readResource(scenario.uri), scenario.expect);
    return;
  }
  if (scenario.kind === "resources.subscribe") {
    await client.subscribeResource(scenario.uri);
    return;
  }
  if (scenario.kind === "resources.unsubscribe") {
    await client.unsubscribeResource(scenario.uri);
    return;
  }
  if (scenario.kind === "prompts.get") {
    assertExpected(
      await client.getPrompt(scenario.prompt, scenario.arguments),
      scenario.expect,
    );
    return;
  }
  throw new McpFnAssertionError(`Unsupported scenario operation ${kind}`);
}

function assertExpected(actual: unknown, expected: unknown): void {
  if (expected !== undefined && stableJson(actual) !== stableJson(expected)) {
    throw new McpFnAssertionError(
      `Scenario result mismatch\nexpected: ${stableJson(expected)}\nactual:   ${stableJson(actual)}`,
    );
  }
}

function isToolScenario(scenario: McpFnScenario): scenario is McpFnToolScenario {
  return "tool" in scenario;
}

function isInventoryScenario(scenario: McpFnScenario): scenario is McpFnInventoryScenario {
  return ["tools.list", "resources.list", "resources.templates.list", "prompts.list"]
    .includes(scenario.kind ?? "");
}
import { createMcpFnClient, streamableHttpTarget } from "@mcpfn/client";

const url = process.argv[2] ?? "http://127.0.0.1:3000/mcp";
const client = createMcpFnClient({ target: streamableHttpTarget(url) });

await client.connect();
try {
  const tools = await client.tools.listAll();
  const result = await client.tools.call("calculator_add", { left: 2, right: 3 });
  process.stdout.write(`${JSON.stringify({ tools, result }, null, 2)}\n`);
} finally {
  await client.close();
}
import { createServer } from "node:http";
import type { AddressInfo } from "node:net";

import createCalculatorServer from "./calculator-server.js";

const mcp = createCalculatorServer();
const handler = await mcp.createWebStandardHandler({ enableJsonResponse: true });

const httpServer = createServer(async (request, response) => {
  try {
    const url = new URL(request.url ?? "/", `http://${request.headers.host ?? "127.0.0.1"}`);
    if (url.pathname !== "/mcp") {
      response.writeHead(404).end("Not found");
      return;
    }

    const chunks: Buffer[] = [];
    for await (const chunk of request) {
      chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
    }
    const body = Buffer.concat(chunks);
    const webRequest = new Request(url, {
      method: request.method,
      headers: new Headers(
        Object.entries(request.headers).flatMap(([key, value]) =>
          Array.isArray(value)
            ? value.map((entry) => [key, entry] as [string, string])
            : value === undefined
              ? []
              : [[key, value] as [string, string]],
        ),
      ),
      ...(body.length > 0 ? { body } : {}),
    });
    const webResponse = await handler(webRequest);
    response.writeHead(
      webResponse.status,
      Object.fromEntries(webResponse.headers.entries()),
    );
    if (!webResponse.body) {
      response.end();
      return;
    }
    const reader = webResponse.body.getReader();
    for (;;) {
      const chunk = await reader.read();
      if (chunk.done) break;
      response.write(Buffer.from(chunk.value));
    }
    response.end();
  } catch {
    if (response.headersSent) {
      response.destroy();
    } else {
      response.writeHead(500, { "content-type": "text/plain" });
      response.end("Internal Server Error");
    }
  }
});

await new Promise<void>((resolve, reject) => {
  httpServer.once("error", reject);
  httpServer.listen(0, "127.0.0.1", resolve);
});

const address = httpServer.address() as AddressInfo;
process.stdout.write(`http://127.0.0.1:${address.port}/mcp\n`);

const close = async () => {
  await mcp.close().catch(() => undefined);
  await new Promise<void>((resolve) => httpServer.close(() => resolve()));
};
process.once("SIGINT", () => void close().then(() => process.exit(0)));
process.once("SIGTERM", () => void close().then(() => process.exit(0)));
import {
  McpFnError,
  McpFnRegistry,
  createMcpFnServer,
  structuredResult,
} from "@mcpfn/core";

const numberResultSchema = {
  type: "object" as const,
  properties: { result: { type: "number" } },
  required: ["result"],
  additionalProperties: false,
};

export default function createCalculatorServer() {
  const registry = new McpFnRegistry()
    .register({
      name: "calculator_sum",
      description: "Add two finite numbers.",
      inputSchema: {
        type: "object",
        properties: {
          left: { type: "number" },
          right: { type: "number" },
        },
        required: ["left", "right"],
        additionalProperties: false,
      },
      outputSchema: numberResultSchema,
      annotations: {
        readOnlyHint: true,
        destructiveHint: false,
        idempotentHint: true,
        openWorldHint: false,
      },
      handler: async ({ left, right }) =>
        structuredResult({ result: Number(left) + Number(right) }),
    })
    .register({
      name: "calculator_divide",
      description: "Divide one finite number by another non-zero number.",
      inputSchema: {
        type: "object",
        properties: {
          dividend: { type: "number" },
          divisor: { type: "number" },
        },
        required: ["dividend", "divisor"],
        additionalProperties: false,
      },
      outputSchema: numberResultSchema,
      annotations: {
        readOnlyHint: true,
        destructiveHint: false,
        idempotentHint: true,
        openWorldHint: false,
      },
      handler: async ({ dividend, divisor }) => {
        if (divisor === 0) {
          throw new McpFnError(
            "CALCULATOR_DIVIDE_BY_ZERO",
            "The divisor must not be zero.",
          );
        }
        return structuredResult({
          result: Number(dividend) / Number(divisor),
        });
      },
    });

  return createMcpFnServer({
    info: {
      name: "mcpfn-calculator-example",
      version: "1.0.0",
      instructions: "Use the calculator tools for deterministic arithmetic.",
    },
    registry,
    transports: ["stdio", "streamable-http"],
  });
}
#!/usr/bin/env node

import { spawnSync } from "node:child_process";
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

const repoRoot = process.cwd();
const nodeMajor = Number.parseInt(process.versions.node.split(".")[0] ?? "0", 10);
if (nodeMajor < 22) {
  console.error(
    JSON.stringify({
      ok: false,
      error: `npm run gate:mcpfn-release requires Node.js 22 or newer for the official conformance runner; current runtime is ${process.versions.node}`,
    }),
  );
  process.exit(1);
}

const temporaryRoot = mkdtempSync(path.join(tmpdir(), "mcpfn-release-"));
const candidateManifest = path.join(temporaryRoot, "calculator.manifest.json");
const scenarioReport = path.join(temporaryRoot, "calculator.report.json");
const results = [];

function run(name, command, args, options = {}) {
  const result = spawnSync(command, args, {
    cwd: options.cwd ?? repoRoot,
    env: {
      ...process.env,
      PATH: [path.dirname(process.execPath), process.env.PATH]
        .filter(Boolean)
        .join(path.delimiter),
    },
    stdio: "pipe",
    encoding: "utf8",
    shell: false,
  });
  const record = {
    name,
    command: [command, ...args].join(" "),
    ok: (result.status ?? 1) === 0,
    status: result.status ?? 1,
    stdout: result.stdout?.trim() ?? "",
    stderr: result.stderr?.trim() ?? "",
  };
  results.push(record);
  if (!record.ok) {
    throw new Error(
      `${name} failed with ${record.status}\n${record.stdout}\n${record.stderr}`,
    );
  }
  return record;
}

function npmStep(name, args, options) {
  return run(name, process.platform === "win32" ? "npm.cmd" : "npm", args, options);
}

function verifyDocumentation() {
  const files = [
    "mcpfn/README.md",
    "mcpfn/ARCHITECTURE.md",
    "mcpfn/ADOPTION.md",
    "mcpfn/TESTING.md",
    "mcpfn/MIGRATION.md",
    "mcpfn/core/README.md",
    "mcpfn/client/README.md",
    "mcpfn/auth/README.md",
    "mcpfn/testing/README.md",
    "mcpfn/inspector/README.md",
    "mcpfn/datafn/README.md",
    "mcpfn/cli/README.md",
  ];
  const missing = [];
  const absolutePaths = [];
  const placeholderFiles = [];
  let gateMentions = 0;
  for (const file of files) {
    let source;
    try {
      source = readFileSync(path.join(repoRoot, file), "utf8");
    } catch {
      missing.push(file);
      continue;
    }
    if (/\/Users\/|\/home\/|[A-Za-z]:\\Users\\/.test(source)) {
      absolutePaths.push(file);
    }
    if (/\b(?:TODO|FIXME|coming soon|placeholder|scaffold)\b/i.test(source)) {
      placeholderFiles.push(file);
    }
    if (source.includes("npm run gate:mcpfn-release")) gateMentions += 1;
  }
  const ok =
    missing.length === 0 &&
    absolutePaths.length === 0 &&
    placeholderFiles.length === 0 &&
    gateMentions >= 2;
  results.push({
    name: "documentation",
    command: "internal documentation inventory",
    ok,
    status: ok ? 0 : 1,
    stdout: JSON.stringify({ files, missing, absolutePaths, placeholderFiles, gateMentions }),
    stderr: "",
  });
  if (!ok) throw new Error("McpFn documentation inventory failed");
}

function verifyPackage(packagePath) {
  const result = npmStep(
    `pack:${packagePath}`,
    ["pack", "--dry-run", "--json"],
    { cwd: path.join(repoRoot, packagePath) },
  );
  const packed = JSON.parse(result.stdout)[0];
  const files = new Set(packed.files.map((entry) => entry.path));
  const requiredFiles = ["README.md", "dist/index.js", "dist/index.cjs", "dist/index.d.ts"];
  if (packagePath === "mcpfn/testing") {
    requiredFiles.push(
      "dist/auth.js",
      "dist/auth.cjs",
      "dist/auth.d.ts",
      "dist/playwright.js",
      "dist/playwright.cjs",
      "dist/playwright.d.ts",
    );
  }
  if (packagePath === "mcpfn/cli") requiredFiles.push("dist/bin.js");
  for (const required of requiredFiles) {
    if (!files.has(required)) {
      throw new Error(`${packagePath} package is missing ${required}`);
    }
  }
  if (packagePath === "mcpfn/cli") {
    const bin = packed.files.find((entry) => entry.path === "dist/bin.js");
    if (!bin || (bin.mode & 0o111) === 0) {
      throw new Error("mcpfn/cli package bin is not executable");
    }
  }
}

function verifyPackedConsumer() {
  const consumerRoot = path.join(temporaryRoot, "consumer");
  mkdirSync(consumerRoot, { recursive: true });
  writeFileSync(
    path.join(consumerRoot, "package.json"),
    JSON.stringify({ private: true, type: "module" }),
  );
  const packagePaths = [
    "packages/auth",
    "packages/observability",
    "packages/db",
    "packages/oauth-storage",
    "packages/oauth-core",
    "mcpfn/core",
