      }
      if (validate) {
        hasStringWitness = [...finiteCandidates].some((candidate) => validate!(candidate));
      }
    }
    if (!hasStringWitness) {
      throw new McpFnValidationError(
        `${label} argument ${name} must accept string values`,
      );
    }
  }
}

