import type { McpFnScenario } from "@mcpfn/testing";

export default [
  {
    name: "adds two numbers",
    tool: "calculator_sum",
    arguments: { left: 2, right: 3 },
    expect: {
      isError: false,
      structuredContent: { result: 5 },
      structuredTextParity: true,
    },
  },
  {
    name: "rejects missing required inputs",
    tool: "calculator_sum",
    arguments: { left: 2 },
    expect: { isError: true },
    verify: (result) => assertTextErrorCode(result, "MCPFN_INVALID_ARGUMENTS"),
  },
  {
    name: "preserves domain error codes",
    tool: "calculator_divide",
    arguments: { dividend: 5, divisor: 0 },
    expect: {
      isError: true,
    },
    verify: (result) => assertTextErrorCode(result, "CALCULATOR_DIVIDE_BY_ZERO"),
  },
] satisfies McpFnScenario[];

function assertTextErrorCode(
  result: { content: unknown[]; structuredContent?: Record<string, unknown> },
  expectedCode: string,
): void {
  if (result.structuredContent !== undefined) {
    throw new Error("A success-only output schema must not receive structured error content");
  }
  const text = result.content.find(
    (entry): entry is { type: "text"; text: string } =>
      !!entry &&
      typeof entry === "object" &&
      (entry as { type?: unknown }).type === "text" &&
      typeof (entry as { text?: unknown }).text === "string",
  )?.text;
  const parsed = JSON.parse(text ?? "null") as { error?: { code?: string } };
  if (parsed?.error?.code !== expectedCode) {
    throw new Error(`Expected error code ${expectedCode}, received ${parsed?.error?.code}`);
  }
}
import { existsSync } from "node:fs";
import path from "node:path";
import { createJiti } from "jiti";
import {
  createManifest,
  validateManifest,
  type McpFnManifest,
  type McpFnRegistry,
  type McpFnServer,
  type McpFnServerInfo,
} from "@mcpfn/core";
import type { McpFnScenario } from "@mcpfn/testing";

async function loadModule(file: string, cwd: string): Promise<unknown> {
  const resolved = path.isAbsolute(file) ? file : path.resolve(cwd, file);
  if (!existsSync(resolved)) {
    throw new Error(`File not found: ${resolved}`);
  }
  if (resolved.endsWith(".json")) {
    return JSON.parse(await import("node:fs/promises").then(({ readFile }) => readFile(resolved, "utf8")));
  }
  const jiti = createJiti(cwd, { moduleCache: false });
  const loaded = (await jiti.import(resolved)) as Record<string, unknown>;
  let value: unknown = loaded.default ?? loaded;
  if (typeof value === "function") value = await value();
  return value;
}

function isServerExport(value: unknown): value is McpFnServer<unknown> {
  return Boolean(
    value &&
    typeof value === "object" &&
    typeof (value as { manifest?: unknown }).manifest === "function" &&
    typeof (value as { connect?: unknown }).connect === "function" &&
    typeof (value as { close?: unknown }).close === "function",
  );
}

function isRegistryExport(value: unknown): value is McpFnRegistry<unknown> {
  return Boolean(
    value &&
    typeof value === "object" &&
    typeof (value as { definitions?: unknown }).definitions === "function" &&
    typeof (value as { listTools?: unknown }).listTools === "function" &&
    typeof (value as { callTool?: unknown }).callTool === "function",
  );
}

export async function loadManifestSource(
  file: string,
  cwd = process.cwd(),
  info?: McpFnServerInfo,
): Promise<{ manifest: McpFnManifest; server?: McpFnServer<unknown> }> {
  const value = await loadModule(file, cwd);
  // Use the public surface instead of instanceof: a global CLI and the target
  // project commonly load separate physical copies of @mcpfn/core.
  if (isServerExport(value)) {
    return { manifest: validateManifest(value.manifest()), server: value };
  }
  if (isRegistryExport(value)) {
    if (!info) {
      throw new Error("A registry source requires --name and --version");
    }
    return { manifest: validateManifest(createManifest(info, value)) };
  }
  return { manifest: validateManifest(value) };
}

export async function loadScenarios(
  file: string,
  cwd = process.cwd(),
): Promise<McpFnScenario[]> {
  const value = await loadModule(file, cwd);
  if (!Array.isArray(value)) {
    throw new Error("Scenario module must default-export an array");
  }
  for (const [index, scenario] of value.entries()) {
    if (
      !scenario ||
      typeof scenario !== "object" ||
      typeof (scenario as { name?: unknown }).name !== "string" ||
      typeof (scenario as { tool?: unknown }).tool !== "string"
    ) {
      throw new Error(`Invalid scenario at index ${index}`);
    }
  }
  return value as McpFnScenario[];
}
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { afterEach, describe, expect, it } from "vitest";
import {
  McpFnRegistry,
  createManifest,
  structuredResult,
} from "@mcpfn/core";

import { loadManifestSource, runCli } from "../src/index.js";

describe("mcpfn CLI", () => {
  const roots: string[] = [];

  afterEach(async () => {
    await Promise.all(roots.splice(0).map((root) => rm(root, { recursive: true, force: true })));
  });

  it("returns usage exit code 2 when a command is missing or unknown", async () => {
    let errors = "";
    expect(await runCli([], { stderr: (value) => { errors += value; } })).toBe(2);
    expect(errors).toContain("A command is required");

    errors = "";
    expect(await runCli(["not-a-command"], {
      stderr: (value) => { errors += value; },
    })).toBe(2);
    expect(errors).toContain("Unknown command: not-a-command");
  });

  it("validates and diffs manifests with stable exit codes", async () => {
    const root = await mkdtemp(path.join(os.tmpdir(), "mcpfn-cli-"));
    roots.push(root);
    const make = (required: string[]) => {
      const registry = new McpFnRegistry().register({
        name: "tool",
        description: "A tool.",
        inputSchema: {
          type: "object",
          properties: { value: { type: "string" }, label: { type: "string" } },
          required,
        },
        handler: async () => structuredResult({ ok: true }),
      });
      return createManifest({ name: "test", version: "1.0.0" }, registry);
    };
    await writeFile(path.join(root, "before.json"), JSON.stringify(make(["value"])));
    await writeFile(path.join(root, "after.json"), JSON.stringify(make(["value", "label"])));
    let output = "";
    expect(await runCli(["validate", "before.json"], { cwd: root, stdout: (value) => { output += value; } })).toBe(0);
    expect(output).toContain("Valid McpFn manifest");
    expect(await runCli(["diff", "before.json", "after.json", "--json"], { cwd: root, stdout: (value) => { output += value; } })).toBe(1);
    expect(JSON.parse(await readFile(path.join(root, "before.json"), "utf8")).formatVersion).toBe(1);
  });

  it("loads a server by public shape across package-instance boundaries", async () => {
    const root = await mkdtemp(path.join(os.tmpdir(), "mcpfn-cli-server-"));
    roots.push(root);
    const manifest = createManifest({ name: "foreign", version: "1.0.0" }, new McpFnRegistry());
    await writeFile(
      path.join(root, "server.mjs"),
      `export default {
        manifest() { return ${JSON.stringify(manifest)}; },
        async connect() {},
        async close() {}
      };`,
    );

    await expect(loadManifestSource("server.mjs", root)).resolves.toMatchObject({
      manifest: { server: { name: "foreign" } },
      server: expect.any(Object),
    });

    await writeFile(
      path.join(root, "registry.mjs"),
      `const tools = ["z", "a"].map((name) => ({
         name, description: name, inputSchema: { type: "object" }, handler: async () => ({ content: [] })
       }));
       export default {
         definitions() { return tools; },
         resourceDefinitions() { return []; },
         resourceTemplateDefinitions() { return []; },
         promptDefinitions() { return []; },
         capabilities() { return { tools: {} }; },
         listTools() { return tools; },
         async callTool() { return { content: [] }; }
       };`,
    );
    await expect(loadManifestSource("registry.mjs", root, {
      name: "foreign",
      version: "1.0.0",
    })).rejects.toThrow(/sorted and unique/);
  });

  it("returns test-failure exit code 1 for a manifest contract mismatch", async () => {
    const root = await mkdtemp(path.join(os.tmpdir(), "mcpfn-cli-mismatch-"));
    roots.push(root);
    const coreUrl = pathToFileURL(
      path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../../core/src/index.ts"),
    ).href;
    const stale = createManifest(
      { name: "mismatch", version: "1.0.0" },
      new McpFnRegistry(),
    );
    await writeFile(
      path.join(root, "server.mjs"),
      `import { McpFnRegistry, createMcpFnServer, structuredResult } from ${JSON.stringify(coreUrl)};
       const actualRegistry = new McpFnRegistry().register({
         name: "actual", description: "Actual tool.", inputSchema: { type: "object" },
         handler: async () => structuredResult({ ok: true })
       });
       const actual = createMcpFnServer({
         info: { name: "mismatch", version: "1.0.0" }, registry: actualRegistry
       });
       const stale = ${JSON.stringify(stale)};
       export default {
         manifest() { return stale; },
         connect(transport) { return actual.connect(transport); },
         close() { return actual.close(); }
       };`,
    );
    await writeFile(path.join(root, "scenarios.mjs"), "export default [];\n");
    let errors = "";
    const exitCode = await runCli(["test", "server.mjs", "scenarios.mjs"], {
      cwd: root,
      stderr: (value) => { errors += value; },
    });
    expect(errors).toContain("Tool inventory mismatch");
    expect(exitCode).toBe(1);
  });
});

