import type { OAuthClientMetadata } from "@modelcontextprotocol/sdk/shared/auth.js";
import { redactOAuthValue } from "@superfunctions/oauth-core";

import {
  matchMcpRedirectUri,
  McpFnRedirectMismatchError,
  type McpFnRedirectPolicy,
} from "./redirects.js";

export type McpFnClientRegistrationSource =
  | "pre-registered"
  | "dynamic"
  | "client-metadata-document"
  | "enterprise";

export interface McpFnNormalizedClientRegistration {
  clientId: string;
  source: McpFnClientRegistrationSource;
  redirectUris: string[];
  responseTypes: string[];
  grantTypes: string[];
  tokenEndpointAuthMethod: string;
  metadata: OAuthClientMetadata;
}

export interface McpFnHostedClientRegistry {
  resolve(clientId: string): Promise<McpFnNormalizedClientRegistration | null>;
  register?(
    metadata: OAuthClientMetadata,
    request: Request,
  ): Promise<McpFnNormalizedClientRegistration>;
}

export interface McpFnValidatedAuthorizationRequest {
  client: McpFnNormalizedClientRegistration;
  responseType: "code";
  redirectUri: string;
  redirectMatch: "exact" | "loopback-dynamic-port";
  codeChallenge: string;
  codeChallengeMethod: "S256";
  scopes: string[];
  state?: string;
  resource?: string;
  raw: URLSearchParams;
}

export class McpFnHostedAuthorizationError extends Error {
  readonly code: string;
  readonly status: number;
  readonly details?: Record<string, unknown>;

  constructor(
    code: string,
    message: string,
    options: { status?: number; details?: Record<string, unknown> } = {},
  ) {
    super(message);
    this.name = "McpFnHostedAuthorizationError";
    this.code = code;
    this.status = options.status ?? 400;
    this.details = options.details;
  }
}

export function normalizeMcpClientRegistration(input: {
  clientId: string;
  source: McpFnClientRegistrationSource;
  metadata: OAuthClientMetadata;
}): McpFnNormalizedClientRegistration {
  if (!input.clientId) {
    throw new McpFnHostedAuthorizationError("invalid_client_metadata", "client_id is required");
  }
  const redirectUris = uniqueUrls(input.metadata.redirect_uris ?? []);
  if (!redirectUris.length) {
    throw new McpFnHostedAuthorizationError(
      "invalid_client_metadata",
      "At least one redirect_uri is required",
    );
  }
  const responseTypes = unique(input.metadata.response_types ?? ["code"]);
  const grantTypes = unique(input.metadata.grant_types ?? ["authorization_code"]);
  return {
    clientId: input.clientId,
    source: input.source,
    redirectUris,
    responseTypes,
    grantTypes,
    tokenEndpointAuthMethod: input.metadata.token_endpoint_auth_method ?? "none",
    metadata: {
      ...input.metadata,
      redirect_uris: redirectUris,
      response_types: responseTypes,
      grant_types: grantTypes,
      token_endpoint_auth_method: input.metadata.token_endpoint_auth_method ?? "none",
    },
  };
}

export function validateMcpAuthorizationRequest(options: {
  url: string | URL;
  client: McpFnNormalizedClientRegistration;
  redirectPolicy?: McpFnRedirectPolicy;
  allowedResources?: ReadonlyArray<string | URL>;
  supportedScopes?: ReadonlyArray<string>;
}): McpFnValidatedAuthorizationRequest {
  const url = new URL(options.url.toString());
  const responseType = url.searchParams.get("response_type");
  if (responseType !== "code" || !options.client.responseTypes.includes("code")) {
    throw new McpFnHostedAuthorizationError(
      "unsupported_response_type",
      "This MCP authorization profile requires response_type=code",
    );
  }
  if (!options.client.grantTypes.includes("authorization_code")) {
    throw new McpFnHostedAuthorizationError(
      "unauthorized_client",
      "The client has no compatible authorization_code flow",
    );
  }
  const requestedClientId = url.searchParams.get("client_id");
  if (requestedClientId !== options.client.clientId) {
    throw new McpFnHostedAuthorizationError("invalid_client", "client_id does not match registration");
  }
  const redirectUri = url.searchParams.get("redirect_uri");
  if (!redirectUri) {
    throw new McpFnHostedAuthorizationError("invalid_request", "redirect_uri is required");
  }
  let redirectMatch;
  try {
    redirectMatch = matchMcpRedirectUri(
      redirectUri,
      options.client.redirectUris,
      options.redirectPolicy,
    );
  } catch (error) {
    if (error instanceof McpFnRedirectMismatchError) {
      throw new McpFnHostedAuthorizationError(
        "invalid_request",
        error.message,
        { details: { phase: "redirect-validation", redirect: error.requested } },
      );
    }
    throw error;
  }
  const codeChallenge = url.searchParams.get("code_challenge");
  if (!codeChallenge) {
    throw new McpFnHostedAuthorizationError("invalid_request", "PKCE code_challenge is required");
  }
  if (url.searchParams.get("code_challenge_method") !== "S256") {
    throw new McpFnHostedAuthorizationError(
      "invalid_request",
      "PKCE code_challenge_method must be S256",
    );
  }
  const resource = url.searchParams.get("resource") ?? undefined;
  if (resource && options.allowedResources?.length) {
    const allowed = new Set(options.allowedResources.map((value) => new URL(value.toString()).toString()));
    if (!allowed.has(new URL(resource).toString())) {
      throw new McpFnHostedAuthorizationError("invalid_target", "resource is not allowed");
    }
  }
  const scopes = unique((url.searchParams.get("scope") ?? "").split(/\s+/).filter(Boolean));
  if (options.supportedScopes) {
    const supported = new Set(options.supportedScopes);
    const unsupported = scopes.filter((scope) => !supported.has(scope));
    if (unsupported.length) {
      throw new McpFnHostedAuthorizationError("invalid_scope", "Requested MCP scope is unsupported", {
        details: { unsupportedScopes: unsupported },
      });
    }
  }
  return {
    client: options.client,
    responseType: "code",
    redirectUri: new URL(redirectUri).toString(),
    redirectMatch: redirectMatch.kind,
    codeChallenge,
    codeChallengeMethod: "S256",
    scopes,
    ...(url.searchParams.get("state") ? { state: url.searchParams.get("state")! } : {}),
    ...(resource ? { resource: new URL(resource).toString() } : {}),
    raw: new URLSearchParams(url.searchParams),
  };
}

export interface McpFnAuthorizationCompatibilityOptions {
  issuer: string | URL;
  clients: McpFnHostedClientRegistry;
  authorize(
    input: McpFnValidatedAuthorizationRequest,
    request: Request,
  ): Promise<Response> | Response;
  token(request: Request): Promise<Response> | Response;
  revoke?(request: Request): Promise<Response> | Response;
  supportedScopes?: string[];
  allowedResources?: Array<string | URL>;
  redirectPolicy?: McpFnRedirectPolicy;
  clientMetadataDocuments?: {
    enabled: boolean;
    /** Required allowlist/policy hook before fetching an external client document. */
    allow?(url: URL): boolean | Promise<boolean>;
    fetch?: typeof globalThis.fetch;
    maxBytes?: number;
    timeoutMs?: number;
    maxRedirects?: number;
  };
  extraMetadata?: Record<string, unknown>;
  diagnostics?(event: {
    phase: string;
    outcome: "succeeded" | "failed";
    code?: string;
    details?: Record<string, unknown>;
  }): void | Promise<void>;
}

/**
 * MCP-specific authorization compatibility router. Identity, login, consent,
 * signing, token issuance, and durable security state stay in the callbacks.
 */
export function createMcpAuthorizationCompatibilityHandler(
  options: McpFnAuthorizationCompatibilityOptions,
): (request: Request) => Promise<Response> {
  validateClientMetadataDocumentOptions(options.clientMetadataDocuments);
  const issuer = new URL(options.issuer.toString());
  issuer.hash = "";
  const endpoint = (path: string) => new URL(path, issuer).toString();
  const metadata = {
    ...options.extraMetadata,
    issuer: issuer.toString(),
    authorization_endpoint: endpoint("/authorize"),
    token_endpoint: endpoint("/token"),
    ...(options.clients.register ? { registration_endpoint: endpoint("/register") } : {}),
    ...(options.revoke ? { revocation_endpoint: endpoint("/revoke") } : {}),
    response_types_supported: ["code"],
    grant_types_supported: ["authorization_code", "refresh_token"],
    code_challenge_methods_supported: ["S256"],
    token_endpoint_auth_methods_supported: ["none", "client_secret_basic", "client_secret_post"],
    ...(options.supportedScopes ? { scopes_supported: unique(options.supportedScopes) } : {}),
    client_id_metadata_document_supported: options.clientMetadataDocuments?.enabled === true,
  };

  return async (request): Promise<Response> => {
    const url = new URL(request.url);
    try {
      if (
        request.method === "GET" &&
        (url.pathname === "/.well-known/oauth-authorization-server" ||
          url.pathname === "/.well-known/openid-configuration")
      ) {
        return json(200, metadata, { "cache-control": "public, max-age=300" });
      }
      if (request.method === "POST" && url.pathname === "/register") {
        if (!options.clients.register) {
          throw new McpFnHostedAuthorizationError(
            "invalid_request",
            "Dynamic client registration is disabled",
            { status: 404 },
          );
        }
        const raw = await readBoundedJson(request, 256_000) as OAuthClientMetadata;
        const metadata = normalizeClientMetadata(raw);
        const registration = await options.clients.register(metadata, request);
        await emit(options, "client-registration", "succeeded", undefined, {
          clientId: registration.clientId,
          source: registration.source,
        });
        return json(201, {
          ...registration.metadata,
          client_id: registration.clientId,
        });
      }
      if (request.method === "GET" && url.pathname === "/authorize") {
        const clientId = url.searchParams.get("client_id");
        if (!clientId) {
          throw new McpFnHostedAuthorizationError("invalid_request", "client_id is required");
        }
        const client = await resolveClient(options, clientId);
        if (!client) {
          throw new McpFnHostedAuthorizationError("invalid_client", "Unknown MCP client");
        }
        const validated = validateMcpAuthorizationRequest({
          url,
          client,
          redirectPolicy: options.redirectPolicy,
          allowedResources: options.allowedResources,
          supportedScopes: options.supportedScopes,
        });
        await emit(options, "authorization-request", "succeeded", undefined, {
          clientId,
          registrationSource: client.source,
          redirectMatch: validated.redirectMatch,
        });
        return options.authorize(validated, request);
      }
      if (request.method === "POST" && url.pathname === "/token") {
        return options.token(request);
      }
      if (request.method === "POST" && url.pathname === "/revoke" && options.revoke) {
        return options.revoke(request);
      }
      return json(404, { error: "not_found" });
    } catch (error) {
      const normalized = error instanceof McpFnHostedAuthorizationError
        ? error
        : new McpFnHostedAuthorizationError(
          "server_error",
          "MCP authorization compatibility processing failed",
          { status: 500 },
        );
      await emit(options, inferPhase(url.pathname), "failed", normalized.code, {
        message: normalized.message,
        ...normalized.details,
      });
      return json(normalized.status, {
        error: normalized.code,
        error_description: normalized.message,
      });
    }
  };
}

async function resolveClient(
  options: McpFnAuthorizationCompatibilityOptions,
  clientId: string,
): Promise<McpFnNormalizedClientRegistration | null> {
  const stored = await options.clients.resolve(clientId);
  if (stored) return stored;
  if (!options.clientMetadataDocuments?.enabled) return null;
  let clientUrl: URL;
  try {
    clientUrl = new URL(clientId);
  } catch {
    return null;
  }
  if (clientUrl.protocol !== "https:" || clientUrl.pathname === "/") return null;
  const raw = await fetchClientMetadataDocument(clientUrl, options.clientMetadataDocuments);
  const record = raw as Record<string, unknown>;
  if (record.client_id !== undefined && record.client_id !== clientId) {
    throw new McpFnHostedAuthorizationError(
      "invalid_client_metadata",
      "Client ID Metadata Document client_id does not match its URL",
    );
  }
  return normalizeMcpClientRegistration({
    clientId,
    source: "client-metadata-document",
    metadata: normalizeClientMetadata(record as OAuthClientMetadata),
  });
}

function normalizeClientMetadata(value: OAuthClientMetadata): OAuthClientMetadata {
  if (!value || typeof value !== "object") {
    throw new McpFnHostedAuthorizationError("invalid_client_metadata", "Client metadata must be an object");
  }
  return {
    ...value,
    redirect_uris: Array.isArray(value.redirect_uris) ? value.redirect_uris : [],
  };
}

async function readBoundedJson(
  source: Request | Response,
  maxBytes: number,
  signal?: AbortSignal,
): Promise<unknown> {
  const contentLength = source.headers.get("content-length");
  if (contentLength !== null) {
    const length = Number(contentLength);
    if (!/^\d+$/.test(contentLength) || !Number.isSafeInteger(length) || length > maxBytes) {
      throw new McpFnHostedAuthorizationError("invalid_request", "Metadata body is too large", {
        status: 413,
      });
    }
  }
  const text = await readBoundedText(source, maxBytes, signal);
  try {
    return JSON.parse(text);
  } catch {
    throw new McpFnHostedAuthorizationError("invalid_request", "Metadata body is not valid JSON");
  }
}

async function fetchClientMetadataDocument(
  initialUrl: URL,
  options: NonNullable<McpFnAuthorizationCompatibilityOptions["clientMetadataDocuments"]>,
): Promise<unknown> {
  const fetchImplementation = options.fetch ?? globalThis.fetch;
  if (!fetchImplementation) throw new Error("A fetch implementation is required");
  const controller = new AbortController();
  const timeout = setTimeout(
    () => controller.abort(),
    options.timeoutMs ?? 10_000,
  );
  (timeout as ReturnType<typeof setTimeout> & { unref?: () => void }).unref?.();
  const maxRedirects = options.maxRedirects ?? 3;
  let currentUrl = new URL(initialUrl);
  try {
    for (let redirectCount = 0; ; redirectCount += 1) {
      await assertClientMetadataDocumentUrlAllowed(currentUrl, options, controller.signal);
      if (controller.signal.aborted) throw clientMetadataTimeoutError();
      let response: Response;
      try {
        response = await withAbort(fetchImplementation(currentUrl, {
            headers: { accept: "application/json" },
            redirect: "manual",
            signal: controller.signal,
          }), controller.signal);
      } catch (error) {
        if (controller.signal.aborted) throw clientMetadataTimeoutError();
        throw error;
      }
      if (isRedirectStatus(response.status)) {
        const location = response.headers.get("location");
        await response.body?.cancel().catch(() => undefined);
        if (!location || redirectCount >= maxRedirects) {
          throw new McpFnHostedAuthorizationError(
            "invalid_client",
            "Client ID Metadata Document redirect could not be followed safely",
          );
        }
        currentUrl = new URL(location, currentUrl);
        continue;
      }
      if (!response.ok) {
        await response.body?.cancel().catch(() => undefined);
        throw new McpFnHostedAuthorizationError(
          "invalid_client",
          "Client ID Metadata Document could not be loaded",
        );
      }
      return await readBoundedJson(
        response,
        options.maxBytes ?? 256_000,
        controller.signal,
      );
    }
  } catch (error) {
    if (controller.signal.aborted) throw clientMetadataTimeoutError();
    throw error;
  } finally {
    clearTimeout(timeout);
  }
}

function clientMetadataTimeoutError(): McpFnHostedAuthorizationError {
  return new McpFnHostedAuthorizationError(
    "invalid_client",
    "Client ID Metadata Document request timed out",
  );
}

async function assertClientMetadataDocumentUrlAllowed(
  url: URL,
  options: NonNullable<McpFnAuthorizationCompatibilityOptions["clientMetadataDocuments"]>,
  signal: AbortSignal,
): Promise<void> {
  if (
    url.protocol !== "https:" ||
    url.username !== "" ||
    url.password !== "" ||
    url.hash !== "" ||
    !options.allow ||
    !(await withAbort(Promise.resolve(options.allow(new URL(url))), signal))
  ) {
    throw new McpFnHostedAuthorizationError(
      "invalid_client",
      "Client ID Metadata Document URL is not permitted",
    );
  }
}

async function readBoundedText(
  source: Request | Response,
  maxBytes: number,
  signal?: AbortSignal,
): Promise<string> {
  if (!source.body) return "";
  const reader = source.body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;
  const onAbort = () => {
    void reader.cancel(new DOMException("aborted", "AbortError")).catch(() => undefined);
  };
  signal?.addEventListener("abort", onAbort, { once: true });
  try {
    if (signal?.aborted) throw new DOMException("aborted", "AbortError");
    while (true) {
      const { done, value } = await reader.read();
      if (signal?.aborted) throw new DOMException("aborted", "AbortError");
      if (done) break;
      total += value.byteLength;
      if (total > maxBytes) {
        await reader.cancel().catch(() => undefined);
        throw new McpFnHostedAuthorizationError("invalid_request", "Metadata body is too large", {
          status: 413,
        });
      }
      chunks.push(value);
    }
  } finally {
    signal?.removeEventListener("abort", onAbort);
    reader.releaseLock();
  }
  const bytes = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return new TextDecoder().decode(bytes);
}

function withAbort<T>(promise: Promise<T>, signal: AbortSignal): Promise<T> {
  if (signal.aborted) return Promise.reject(new DOMException("aborted", "AbortError"));
  return new Promise<T>((resolve, reject) => {
    const onAbort = () => {
      cleanup();
      reject(new DOMException("aborted", "AbortError"));
    };
    const cleanup = () => signal.removeEventListener("abort", onAbort);
import { createHash, randomBytes, randomUUID } from "node:crypto";
import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
import type { AddressInfo } from "node:net";

import type { AuthInfo } from "@modelcontextprotocol/sdk/server/auth/types.js";

import {
  assertAuthorizationCodeClientMetadata,
  createOAuthClientMetadataVariants,
  type McpFnOAuthClientMetadataVariants,
} from "./auth-core.js";

interface AuthorizationCodeRecord {
  clientId: string;
  redirectUri: string;
  codeChallenge: string;
  scopes: string[];
  resource?: string;
  expiresAt: number;
  used: boolean;
}

interface AccessTokenRecord {
  clientId: string;
  scopes: string[];
  resource?: string;
  expiresAt: number;
  revoked: boolean;
}

interface RefreshTokenRecord {
  clientId: string;
  scopes: string[];
  resource?: string;
  expiresAt: number;
  revoked: boolean;
}

export interface McpFnMockOAuthServerOptions {
  issuer: string | URL;
  clientId?: string;
  redirectUris?: string[];
  scopesSupported?: string[];
  accessTokenLifetimeSeconds?: number;
  authorizationCodeLifetimeSeconds?: number;
  refreshTokenLifetimeSeconds?: number;
  clock?: () => number;
}

export interface McpFnMockOAuthTokenSet {
  access_token: string;
  token_type: "Bearer";
  expires_in: number;
  refresh_token: string;
  scope: string;
  resource?: string;
}

export interface McpFnPkcePair {
  verifier: string;
  challenge: string;
  method: "S256";
}

export interface McpFnOAuthCallback {
  url: string;
  parameters: Record<string, string>;
}

function base64Url(value: Buffer): string {
  return value.toString("base64url");
}

export function createPkcePair(): McpFnPkcePair {
  const verifier = base64Url(randomBytes(48));
  return {
    verifier,
    challenge: createHash("sha256").update(verifier).digest("base64url"),
    method: "S256",
  };
}

function uniqueScopes(value: string | null | undefined): string[] {
  return [...new Set((value ?? "").split(/\s+/).filter(Boolean))].sort();
}

function json(status: number, body: unknown): Response {
  return Response.json(body, {
    status,
    headers: { "cache-control": "no-store" },
  });
}

function oauthError(status: number, error: string, description: string): Response {
  return json(status, { error, error_description: description });
}

function escapeHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll('"', "&quot;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;");
}

function formValue(form: URLSearchParams, name: string): string | undefined {
  const value = form.get(name);
  return value === null || value === "" ? undefined : value;
}

export class McpFnMockOAuthAuthorizationServer {
  readonly issuer: URL;
  readonly clientId: string;
  readonly redirectUris: string[];
  readonly scopesSupported: string[];
  readonly clientMetadata: McpFnOAuthClientMetadataVariants;

  private readonly codes = new Map<string, AuthorizationCodeRecord>();
  private readonly accessTokens = new Map<string, AccessTokenRecord>();
  private readonly refreshTokens = new Map<string, RefreshTokenRecord>();
  private readonly callbacks: McpFnOAuthCallback[] = [];
  private readonly clock: () => number;
  private readonly accessTokenLifetimeSeconds: number;
  private readonly authorizationCodeLifetimeSeconds: number;
  private readonly refreshTokenLifetimeSeconds: number;

  constructor(options: McpFnMockOAuthServerOptions) {
    this.issuer = new URL(options.issuer);
    this.issuer.pathname = this.issuer.pathname.replace(/\/?$/, "/");
    this.clientId = options.clientId ?? "mcpfn-playwright";
    this.redirectUris = options.redirectUris?.map((uri) => new URL(uri).toString()) ?? [
      new URL("callback", this.issuer).toString(),
    ];
    this.scopesSupported = [...new Set(options.scopesSupported ?? ["mcp:read", "mcp:write"])].sort();
    this.clock = options.clock ?? Date.now;
    this.accessTokenLifetimeSeconds = options.accessTokenLifetimeSeconds ?? 300;
    this.authorizationCodeLifetimeSeconds = options.authorizationCodeLifetimeSeconds ?? 120;
    this.refreshTokenLifetimeSeconds = options.refreshTokenLifetimeSeconds ?? 3_600;
    this.clientMetadata = createOAuthClientMetadataVariants(
      this.issuer,
      this.redirectUris[0],
    );
  }

  get metadataUrl(): string {
    return new URL(".well-known/oauth-authorization-server", this.issuer).toString();
  }

  get authorizationEndpoint(): string {
    return new URL("authorize", this.issuer).toString();
  }

  get tokenEndpoint(): string {
    return new URL("token", this.issuer).toString();
  }

  get revocationEndpoint(): string {
    return new URL("revoke", this.issuer).toString();
  }

  get callbackUrl(): string {
    return this.redirectUris[0];
  }

  clientMetadataUrl(
    variant: keyof McpFnOAuthClientMetadataVariants,
  ): string {
    return this.clientMetadata[variant].client_id;
  }

  authorizationUrl(input: {
    clientId?: string;
    redirectUri?: string;
    codeChallenge: string;
    state?: string;
    scopes?: string[];
    resource?: string;
    extraParameters?: Record<string, string>;
  }): string {
    const url = new URL(this.authorizationEndpoint);
    url.searchParams.set("response_type", "code");
    url.searchParams.set("client_id", input.clientId ?? this.clientId);
    url.searchParams.set("redirect_uri", input.redirectUri ?? this.callbackUrl);
    url.searchParams.set("code_challenge", input.codeChallenge);
    url.searchParams.set("code_challenge_method", "S256");
    url.searchParams.set("scope", (input.scopes ?? ["mcp:read"]).join(" "));
    if (input.state) url.searchParams.set("state", input.state);
    if (input.resource) url.searchParams.set("resource", input.resource);
    for (const [name, value] of Object.entries(input.extraParameters ?? {})) {
      url.searchParams.set(name, value);
    }
    return url.toString();
  }

  latestCallback(): McpFnOAuthCallback | undefined {
    return this.callbacks.at(-1);
  }

  expireAccessToken(token: string): void {
    const record = this.accessTokens.get(token);
    if (record) record.expiresAt = this.nowSeconds() - 1;
  }

  revokeToken(token: string): void {
    const access = this.accessTokens.get(token);
    if (access) access.revoked = true;
    const refresh = this.refreshTokens.get(token);
    if (refresh) refresh.revoked = true;
  }

  async verifyAccessToken(token: string): Promise<AuthInfo> {
    const record = this.accessTokens.get(token);
    if (!record || record.revoked || record.expiresAt <= this.nowSeconds()) {
      throw new Error("Invalid access token");
    }
    return {
      token,
      clientId: record.clientId,
      scopes: record.scopes,
      expiresAt: record.expiresAt,
      ...(record.resource ? { resource: new URL(record.resource) } : {}),
    };
  }

  async handle(request: Request): Promise<Response> {
    const url = new URL(request.url);
    const path = url.pathname.replace(this.issuer.pathname.replace(/\/$/, ""), "") || "/";
    if (request.method === "GET" && path === "/.well-known/oauth-authorization-server") {
      return json(200, {
        issuer: this.issuer.toString(),
        authorization_endpoint: this.authorizationEndpoint,
        token_endpoint: this.tokenEndpoint,
        revocation_endpoint: this.revocationEndpoint,
        response_types_supported: ["code"],
        grant_types_supported: ["authorization_code", "refresh_token"],
        code_challenge_methods_supported: ["S256"],
        token_endpoint_auth_methods_supported: ["none"],
        scopes_supported: this.scopesSupported,
      });
    }

    if (request.method === "GET" && path.startsWith("/client-metadata/")) {
      const metadata = Object.values(this.clientMetadata)
        .find((candidate) => new URL(candidate.client_id).pathname === url.pathname);
      return metadata ? json(200, metadata) : json(404, { error: "not_found" });
    }

    if (request.method === "GET" && path === "/authorize") {
      return this.authorize(url);
    }
    if (request.method === "POST" && path === "/token") {
      return this.token(await request.text());
    }
    if (request.method === "POST" && path === "/revoke") {
      return this.revoke(await request.text());
    }
    if (request.method === "GET" && path === "/callback") {
      const parameters = Object.fromEntries(url.searchParams);
      this.callbacks.push({ url: url.toString(), parameters });
      return new Response(
        `<!doctype html><html><body><main><h1>OAuth callback received</h1><pre>${escapeHtml(JSON.stringify(parameters, null, 2))}</pre></main></body></html>`,
        { headers: { "content-type": "text/html; charset=utf-8" } },
      );
    }
    return json(404, { error: "not_found" });
  }

  private nowSeconds(): number {
    return Math.floor(this.clock() / 1_000);
  }

  private resolveClient(clientId: string): { clientId: string; redirectUris: string[] } | undefined {
    if (clientId === this.clientId) {
      return { clientId, redirectUris: this.redirectUris };
    }
    const metadata = Object.values(this.clientMetadata)
      .find((candidate) => candidate.client_id === clientId);
    if (!metadata) return undefined;
    assertAuthorizationCodeClientMetadata(metadata, clientId);
    return { clientId, redirectUris: metadata.redirect_uris };
  }

  private authorize(url: URL): Response {
    const clientId = url.searchParams.get("client_id") ?? "";
    const redirectUri = url.searchParams.get("redirect_uri") ?? "";
    const client = this.resolveClient(clientId);
    if (!client) return oauthError(400, "invalid_client", "Unknown OAuth client");
    if (!client.redirectUris.includes(redirectUri)) {
      return oauthError(400, "invalid_request", "redirect_uri is not registered");
    }
    if (url.searchParams.get("response_type") !== "code") {
      return this.authorizationRedirect(url, redirectUri, "unsupported_response_type");
    }
    const codeChallenge = url.searchParams.get("code_challenge");
    if (!codeChallenge || url.searchParams.get("code_challenge_method") !== "S256") {
      return this.authorizationRedirect(url, redirectUri, "invalid_request", "PKCE S256 is required");
    }
    const requestedScopes = uniqueScopes(url.searchParams.get("scope"));
    if (requestedScopes.some((scope) => !this.scopesSupported.includes(scope))) {
      return this.authorizationRedirect(url, redirectUri, "invalid_scope");
    }
    const decision = url.searchParams.get("decision");
    if (!decision) {
      const hidden = [...url.searchParams]
        .filter(([name]) => name !== "decision")
        .map(([name, value]) => `<input type="hidden" name="${escapeHtml(name)}" value="${escapeHtml(value)}">`)
        .join("");
      return new Response(
        `<!doctype html><html><body><main><h1>Authorize MCP client</h1><p>${escapeHtml(clientId)}</p><form method="get" action="${escapeHtml(this.authorizationEndpoint)}">${hidden}<button name="decision" value="approve">Approve</button><button name="decision" value="deny">Deny</button></form></main></body></html>`,
        { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } },
      );
    }
    if (decision === "deny") {
      return this.authorizationRedirect(url, redirectUri, "access_denied");
    }
    if (decision !== "approve") {
      return oauthError(400, "invalid_request", "Unknown authorization decision");
    }
    const code = `mcpfn_code_${randomUUID()}`;
    this.codes.set(code, {
      clientId,
      redirectUri,
      codeChallenge,
      scopes: requestedScopes,
      resource: url.searchParams.get("resource") ?? undefined,
      expiresAt: this.nowSeconds() + this.authorizationCodeLifetimeSeconds,
      used: false,
    });
    const callback = new URL(redirectUri);
    callback.searchParams.set("code", code);
    const state = url.searchParams.get("state");
    if (state) callback.searchParams.set("state", state);
    return Response.redirect(callback, 302);
  }

  private authorizationRedirect(
    requestUrl: URL,
    redirectUri: string,
    error: string,
    description?: string,
  ): Response {
    const callback = new URL(redirectUri);
    callback.searchParams.set("error", error);
    if (description) callback.searchParams.set("error_description", description);
    const state = requestUrl.searchParams.get("state");
    if (state) callback.searchParams.set("state", state);
    return Response.redirect(callback, 302);
  }

  private token(source: string): Response {
    const form = new URLSearchParams(source);
    const grantType = formValue(form, "grant_type");
    if (grantType === "authorization_code") return this.exchangeAuthorizationCode(form);
    if (grantType === "refresh_token") return this.exchangeRefreshToken(form);
    return oauthError(400, "unsupported_grant_type", "The grant type is not supported");
  }

  private exchangeAuthorizationCode(form: URLSearchParams): Response {
    const code = formValue(form, "code");
    const record = code ? this.codes.get(code) : undefined;
    if (!record || record.used || record.expiresAt <= this.nowSeconds()) {
      return oauthError(400, "invalid_grant", "Authorization code is invalid or expired");
    }
    if (
      formValue(form, "client_id") !== record.clientId ||
      formValue(form, "redirect_uri") !== record.redirectUri
    ) {
      return oauthError(400, "invalid_grant", "Authorization code binding does not match");
    }
    const verifier = formValue(form, "code_verifier");
    const challenge = verifier
      ? createHash("sha256").update(verifier).digest("base64url")
      : undefined;
    if (challenge !== record.codeChallenge) {
      return oauthError(400, "invalid_grant", "PKCE verification failed");
    }
    record.used = true;
    return json(200, this.issueTokenSet(record));
  }

  private exchangeRefreshToken(form: URLSearchParams): Response {
    const refreshToken = formValue(form, "refresh_token");
    const record = refreshToken ? this.refreshTokens.get(refreshToken) : undefined;
    if (!record || record.revoked || record.expiresAt <= this.nowSeconds()) {
      return oauthError(400, "invalid_grant", "Refresh token is invalid or expired");
    }
    if (formValue(form, "client_id") !== record.clientId) {
      return oauthError(400, "invalid_grant", "Refresh token client binding does not match");
    }
    const requestedScopes = form.has("scope")
      ? uniqueScopes(form.get("scope"))
      : record.scopes;
    if (requestedScopes.some((scope) => !record.scopes.includes(scope))) {
      return oauthError(400, "invalid_scope", "Refresh cannot increase granted scopes");
    }
    record.revoked = true;
