async function assertClientMetadataDocumentUrlAllowed(
  url: URL,
  options: NonNullable<McpFnAuthorizationCompatibilityOptions["clientMetadataDocuments"]>,
  signal: AbortSignal,
): Promise<void> {
  if (
    url.protocol !== "https:" ||
    url.username !== "" ||
    url.password !== "" ||
    url.hash !== "" ||
