        "MCPFN_AUTH_CALLBACK_FAILED",
        "Failed to exchange the MCP authorization callback",
        { phase: "token-exchange", cause: error },
      );
    }
    await this.cleanupAttempt();
    this._state = "idle";
    await this.connect();
