  getServerVersion(): Implementation | undefined {
    return this._protocol?.getServerVersion();
  }

  getTargetDescriptor() {
    return this.options.target.describe();
  }

  onDiagnostic(listener: McpFnDiagnosticSink): () => void {
    this.listeners.add(listener);
