      return json(200, metadata, { "cache-control": "public, max-age=300" });
    }

    const token = readBearerToken(request);
    if (!token) {
      return bearerChallengeResponse(401, metadataUrl, {
        error: "invalid_token",
        description: "A Bearer access token is required",
      });
