    if (
      !authInfo.resource ||
      normalizeResource(authInfo.resource).toString() !== resource.toString()
    ) {
      return bearerChallengeResponse(401, metadataUrl, {
        error: "invalid_token",
        description: "The access token is not bound to this resource",
      });
