  const chunks: Buffer[] = [];
  for await (const chunk of req) chunks.push(Buffer.from(chunk));
  const headers = new Headers();
  for (const [name, value] of Object.entries(req.headers)) {
    if (Array.isArray(value)) {
      for (const entry of value) headers.append(name, entry);
    } else if (value !== undefined) {
      headers.set(name, value);
    }
  }
  const body = chunks.length ? Buffer.concat(chunks) : undefined;
  const init: RequestInit & { duplex?: "half" } = {
    method: req.method,
    headers,
    ...(body ? { body, duplex: "half" } : {}),
  };
  return new Request(new URL(req.url ?? "/", origin), init);
}

async function writeResponse(res: ServerResponse, response: Response): Promise<void> {
  res.statusCode = response.status;
  response.headers.forEach((value, name) => res.setHeader(name, value));
  res.end(Buffer.from(await response.arrayBuffer()));
}

export async function startMockOAuthAuthorizationServer(
  options: McpFnStartMockOAuthServerOptions = {},
): Promise<McpFnStartedMockOAuthServer> {
  let oauth: McpFnMockOAuthAuthorizationServer | undefined;
  let origin = "";
  const server = createServer(async (req, res) => {
    try {
      if (!oauth) throw new Error("Mock OAuth server is not initialized");
      await writeResponse(res, await oauth.handle(await toRequest(req, origin)));
    } catch {
      res.statusCode = 500;
      res.setHeader("content-type", "application/json");
      res.end(JSON.stringify({
        error: "server_error",
        error_description: "Internal Server Error",
      }));
    }
  });
  await new Promise<void>((resolve, reject) => {
    server.once("error", reject);
    server.listen(options.port ?? 0, options.hostname ?? "127.0.0.1", () => {
      server.off("error", reject);
      resolve();
    });
  });
  const address = server.address() as AddressInfo;
  origin = `http://${address.address.includes(":") ? `[${address.address}]` : address.address}:${address.port}`;
  oauth = new McpFnMockOAuthAuthorizationServer({ ...options, issuer: origin });
  return {
    origin,
    oauth,
    close: () => new Promise<void>((resolve, reject) => {
      server.close((error) => error ? reject(error) : resolve());
    }),
  };
}
import { afterEach, describe, expect, it } from "vitest";

import {
  createPkcePair,
  startMockOAuthAuthorizationServer,
  type McpFnStartedMockOAuthServer,
} from "../src/auth.js";

describe("McpFn mock OAuth authorization server", () => {
  let started: McpFnStartedMockOAuthServer | undefined;
  afterEach(async () => {
    await started?.close();
    started = undefined;
  });

  it("runs authorization-code PKCE, refresh rotation, revocation, and extensible CIMD", async () => {
    started = await startMockOAuthAuthorizationServer();
    const oauth = started.oauth;
    const metadata = await fetch(oauth.metadataUrl).then((response) => response.json());
    expect(metadata).toMatchObject({
      issuer: `${started.origin}/`,
      authorization_endpoint: oauth.authorizationEndpoint,
      grant_types_supported: ["authorization_code", "refresh_token"],
      code_challenge_methods_supported: ["S256"],
    });

    const clientId = oauth.clientMetadataUrl("deviceCodeExtension");
    const clientMetadata = await fetch(clientId).then((response) => response.json()) as {
      grant_types: string[];
    };
    expect(clientMetadata.grant_types).toContain(
      "urn:ietf:params:oauth:grant-type:device_code",
    );

    const pkce = createPkcePair();
    const authorizationUrl = new URL(oauth.authorizationUrl({
      clientId,
      codeChallenge: pkce.challenge,
      state: "state-1",
      scopes: ["mcp:read"],
      resource: "https://mcp.example.com/mcp",
    }));
    const consent = await fetch(authorizationUrl, { redirect: "manual" });
    expect(consent.status).toBe(200);
    await expect(consent.text()).resolves.toContain("Authorize MCP client");

    authorizationUrl.searchParams.set("decision", "approve");
    const approval = await fetch(authorizationUrl, { redirect: "manual" });
    expect(approval.status).toBe(302);
    const callback = new URL(approval.headers.get("location") ?? "");
    expect(callback.searchParams.get("state")).toBe("state-1");
    const code = callback.searchParams.get("code") ?? "";

    const exchange = () => fetch(oauth.tokenEndpoint, {
      method: "POST",
      headers: { "content-type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({
        grant_type: "authorization_code",
        client_id: clientId,
        redirect_uri: oauth.callbackUrl,
        code,
        code_verifier: pkce.verifier,
      }),
    });
    const wrongVerifier = await fetch(oauth.tokenEndpoint, {
      method: "POST",
      headers: { "content-type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({
        grant_type: "authorization_code",
        client_id: clientId,
        redirect_uri: oauth.callbackUrl,
        code,
        code_verifier: "wrong-verifier-that-is-long-enough-to-be-valid-but-does-not-match",
      }),
    });
    expect(wrongVerifier.status).toBe(400);
    await expect(wrongVerifier.json()).resolves.toMatchObject({ error: "invalid_grant" });
    const tokenResponse = await exchange();
    expect(tokenResponse.status).toBe(200);
    const tokens = await tokenResponse.json() as {
      access_token: string;
      refresh_token: string;
      resource: string;
    };
    const verified = await oauth.verifyAccessToken(tokens.access_token);
    expect(verified).toMatchObject({
      clientId,
      scopes: ["mcp:read"],
    });
    expect(verified.resource?.href).toBe("https://mcp.example.com/mcp");
    expect((await exchange()).status).toBe(400);

    const refresh = (refreshToken = tokens.refresh_token) => fetch(oauth.tokenEndpoint, {
      method: "POST",
      headers: { "content-type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({
        grant_type: "refresh_token",
        client_id: clientId,
        refresh_token: refreshToken,
      }),
    });
    const refreshResponse = await refresh();
    expect(refreshResponse.status).toBe(200);
    const refreshed = await refreshResponse.json() as {
      access_token: string;
      refresh_token: string;
    };
    expect(refreshed.refresh_token).not.toBe(tokens.refresh_token);
    await expect(oauth.verifyAccessToken(refreshed.access_token)).resolves.toMatchObject({ clientId });
    expect((await refresh(refreshed.refresh_token)).status).toBe(200);
    expect((await refresh()).status).toBe(400);

    expect((await fetch(oauth.tokenEndpoint, {
      method: "POST",
      headers: { "content-type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({ grant_type: "password" }),
    })).status).toBe(400);

    await fetch(oauth.revocationEndpoint, {
      method: "POST",
      headers: { "content-type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({ token: refreshed.access_token }),
    });
    await expect(oauth.verifyAccessToken(refreshed.access_token)).rejects.toThrow(
      "Invalid access token",
    );
  });
});

  it("reports degraded and incompatible host-profile matches", () => {
    const registry = new McpFnRegistry()
      .register({
        name: "requires_host",
        description: "Use host features.",
        inputSchema: { type: "object" },
        handler: async () => structuredResult({ ok: true }),
      })
      .registerPrompt({
        name: "hello",
        get: async () => ({
          messages: [{ role: "user", content: { type: "text", text: "Hello" } }],
        }),
      });
    const server = createMcpFnServer({
      info: { name: "profiles", version: "1.0.0" },
      registry,
      protocolVersions: ["2025-11-25"],
      clientRequirements: { sampling: true },
    });
    const toolsOnly = checkHostCompatibility(
      server.manifest(),
      MCPFN_HOST_PROFILES.toolsOnly,
    );
    expect(toolsOnly).toMatchObject({ status: "incompatible", compatible: false });
    expect(toolsOnly.issues).toEqual(expect.arrayContaining([
      expect.objectContaining({ code: "sampling-required" }),
      expect.objectContaining({ code: "server-feature-unavailable", path: "capabilities.prompts" }),
    ]));
    expect(checkHostCompatibility(
      server.manifest(),
      MCPFN_HOST_PROFILES.fullProtocol,
    )).toMatchObject({ status: "compatible", compatible: true });

    const optionalPromptServer = createMcpFnServer({
      info: { name: "optional-prompts", version: "1.0.0" },
      registry: new McpFnRegistry().registerPrompt({
        name: "optional",
        get: async () => ({ messages: [] }),
      }),
      protocolVersions: ["2025-11-25"],
    });
    expect(checkHostCompatibility(
      optionalPromptServer.manifest(),
      MCPFN_HOST_PROFILES.toolsOnly,
    )).toMatchObject({
      status: "degraded",
      compatible: true,
      issues: [expect.objectContaining({
        code: "server-feature-unavailable",
        path: "capabilities.prompts",
      })],
    });
  });
});
