  const { schemaFields, readable } = fieldMaps(schema, resource);
  for (const field of fields) {
    if (field !== "id" && !schemaFields.has(field)) {
      throw new McpFnValidationError(
        `Unknown exposed field ${resource.name}.${field}`,
