160	/** Convert an observed production-client operation into the shared runner contract. */
161	export function createMcpFnScenario(
162	  name: string,
163	  operation: McpFnRecordedOperation,
164	  result: McpFnRecordedOperationResult,
165	): McpFnScenario {
166	  if (operation.kind === "tools.call") {
167	    const toolResult = result as CallToolResult;
168	    return {
169	      formatVersion: 1,
170	      name,
171	      kind: "tools.call",
172	      sideEffect: "non-idempotent",
173	      tool: operation.name,
174	      ...(operation.arguments ? { arguments: operation.arguments } : {}),
175	      expect: {
176	        isError: Boolean(toolResult.isError),
177	        ...(toolResult.structuredContent !== undefined
178	          ? { structuredContent: toolResult.structuredContent }
179	          : {}),
180	      },
181	    };
182	  }
183	  if (operation.kind === "tools.call:task") {
184	    return {
185	      formatVersion: 1,
186	      name,
187	      kind: "tools.call:task",
188	      sideEffect: "non-idempotent",
189	      tool: operation.name,
190	      ...(operation.arguments ? { arguments: operation.arguments } : {}),
191	      ...(operation.task ? { task: operation.task } : {}),
192	    };
193	  }
194	  if (operation.kind === "resources.read") {
195	    return {
196	      formatVersion: 1,
197	      name,
198	      kind: "resources.read",
199	      sideEffect: "none",
200	      uri: operation.uri,
201	      expect: result,
202	    };
203	  }
204	  if (operation.kind === "resources.subscribe" || operation.kind === "resources.unsubscribe") {
205	    return {
206	      formatVersion: 1,
207	      name,
208	      kind: operation.kind,
209	      sideEffect: "idempotent",
210	      uri: operation.uri,
211	    };
212	  }
213	  if (operation.kind === "tasks.get" || operation.kind === "tasks.cancel") {
214	    return {
215	      formatVersion: 1,
216	      name,
217	      kind: operation.kind,
218	      sideEffect: operation.kind === "tasks.cancel" ? "idempotent" : "none",
219	      taskId: operation.taskId,
220	    };
221	  }
222	  if (operation.kind === "tasks.result") {
223	    return {
224	      formatVersion: 1,
225	      name,
226	      kind: operation.kind,
227	      sideEffect: "none",
228	      taskId: operation.taskId,
229	      expect: result,
230	    };
231	  }
232	  if (operation.kind === "tasks.list") {
233	    return {
234	      formatVersion: 1,
235	      name,
236	      kind: operation.kind,
237	      sideEffect: "none",
238	      ...(operation.cursor ? { cursor: operation.cursor } : {}),
239	    };
240	  }
241	  return {
242	    formatVersion: 1,
243	    name,
244	    kind: "prompts.get",
245	    sideEffect: "none",
246	    prompt: operation.name,
247	    ...(operation.arguments ? { arguments: operation.arguments } : {}),
248	    expect: result,
249	  };
250	}
