477	export interface McpFnScenarioRunOptions {
478	  defaultTimeoutMs?: number;
479	  maxScenarios?: number;
480	  maxErrorBytes?: number;
481	  variables?: Record<string, string | undefined>;
482	  auth?(scenario: McpFnAuthScenario, signal: AbortSignal): Promise<{
483	    outcome: "allowed" | "denied";
484	    code?: string;
485	  }>;
486	}
487	
488	function resolveScenarioVariables(
489	  scenario: McpFnScenario,
490	  supplied: Record<string, string | undefined> | undefined,
491	): { scenario: McpFnScenario; missing: string[] } {
492	  const values = { ...process.env, ...supplied };
493	  const required = new Set(scenario.variables ?? []);
494	  const marker = /\$\{([A-Z][A-Z0-9_]*)\}/g;
495	  const visit = (value: unknown): unknown => {
496	    if (typeof value === "string") {
497	      for (const match of value.matchAll(marker)) required.add(match[1]);
498	      return value.replace(marker, (original, name: string) => values[name] ?? original);
499	    }
500	    if (Array.isArray(value)) return value.map(visit);
501	    if (value && typeof value === "object") {
502	      return Object.fromEntries(
503	        Object.entries(value as Record<string, unknown>).map(([key, entry]) => [key, visit(entry)]),
504	      );
505	    }
506	    return value;
507	  };
508	  const resolved = visit(scenario) as McpFnScenario;
509	  return {
510	    scenario: resolved,
511	    missing: [...required].filter((name) => values[name] === undefined).sort(),
512	  };
513	}
514	
515	export function createMcpFnScenarioReport(
516	  results: McpFnScenarioResult[],
517	  options: { manifestHash?: string; maxBytes?: number } = {},
518	): McpFnScenarioReport {
519	  const failed = results.filter((result) => result.status === "failed").length;
520	  const incomplete = results.filter((result) => result.status === "incomplete").length;
521	  const report: McpFnScenarioReport = {
522	    formatVersion: 1,
523	    kind: "mcpfn.scenario-report",
524	    status: incomplete === 0 ? "complete" : "incomplete",
525	    ...(options.manifestHash ? { manifestHash: options.manifestHash } : {}),
526	    total: results.length,
527	    passed: results.length - failed - incomplete,
528	    failed,
529	    incomplete,
530	    droppedResults: 0,
531	    results: structuredClone(results),
532	  };
533	  const maxBytes = options.maxBytes ?? 1_048_576;
534	  if (!Number.isInteger(maxBytes) || maxBytes < 1_024) {
535	    throw new Error("maxBytes must be an integer of at least 1024");
536	  }
537	  if (serializedBytes(report) > maxBytes) {
538	    report.status = "incomplete";
539	    report.incompleteReason = "Report content exceeded maxBytes and was truncated";
540	  }
541	  while (serializedBytes(report) > maxBytes && report.results.length > 0) {
542	    report.results.pop();
543	    report.droppedResults += 1;
544	  }
545	  if (report.droppedResults > 0) {
546	    report.status = "incomplete";
547	  }
548	  if (serializedBytes(report) > maxBytes) {
549	    throw new Error("The minimum scenario report exceeds maxBytes");
550	  }
551	  return report;
552	}
553	
554	function serializedBytes(value: unknown): number {
555	  return new TextEncoder().encode(JSON.stringify(value)).byteLength;
556	}
557	
558	async function executeScenario(
559	  client: McpFnTestClient<unknown>,
560	  scenario: McpFnScenario,
561	  requestOptions: { signal: AbortSignal; timeout: number },
562	  observedEvents: McpFnClientEvent[],
563	  runOptions: McpFnScenarioRunOptions,
564	): Promise<void> {
565	  const kind = scenario.kind ?? "tools.call";
566	  if (kind === "tools.call" && isToolScenario(scenario)) {
567	    const result = await client.callToolWithOptions(
568	      scenario.tool,
569	      scenario.arguments,
570	      requestOptions,
571	    );
572	    if (result.isError && scenario.expect?.isError === undefined) {
573	      throw new McpFnAssertionError(
574	        "Tool returned isError=true without an explicit expect.isError=true assertion",
575	      );
576	    }
577	    if (
578	      scenario.expect?.isError !== undefined &&
579	      Boolean(result.isError) !== scenario.expect.isError
580	    ) {
581	      throw new McpFnAssertionError(
582	        `Expected isError=${scenario.expect.isError}, received ${Boolean(result.isError)}`,
583	      );
584	    }
585	    if (
586	      scenario.expect &&
587	      Object.prototype.hasOwnProperty.call(scenario.expect, "structuredContent") &&
588	      stableJson(result.structuredContent) !== stableJson(scenario.expect.structuredContent)
589	    ) {
590	      throw new McpFnAssertionError(
591	        `Structured result mismatch\nexpected: ${stableJson(scenario.expect.structuredContent)}\nactual:   ${stableJson(result.structuredContent)}`,
592	      );
593	    }
594	    if (scenario.expect?.structuredTextParity) assertStructuredTextParity(result);
595	    await scenario.verify?.(result);
596	    return;
597	  }
598	  if (kind === "initialize" && scenario.kind === "initialize") {
599	    const actual = client.client.getServerCapabilities() ?? {};
600	    if (scenario.expectCapabilities && stableJson(actual) !== stableJson(scenario.expectCapabilities)) {
601	      throw new McpFnAssertionError(
602	        `Capability mismatch\nexpected: ${stableJson(scenario.expectCapabilities)}\nactual:   ${stableJson(actual)}`,
603	      );
604	    }
605	    return;
606	  }
607	  if (isInventoryScenario(scenario)) {
608	    const values = kind === "tools.list"
609	      ? await client.listTools(requestOptions)
610	      : kind === "resources.list"
611	        ? await client.listResources(requestOptions)
612	        : kind === "resources.templates.list"
613	          ? await client.listResourceTemplates(requestOptions)
614	          : await client.listPrompts(requestOptions);
615	    if (scenario.expectNames) {
616	      const actual = values.map((value) => value.name).sort();
617	      const expected = [...scenario.expectNames].sort();
618	      if (stableJson(actual) !== stableJson(expected)) {
619	        throw new McpFnAssertionError(
620	          `Inventory mismatch\nexpected: ${stableJson(expected)}\nactual:   ${stableJson(actual)}`,
621	        );
622	      }
623	    }
624	    return;
625	  }
626	  if (scenario.kind === "resources.read") {
627	    assertExpected(
628	      await client.readResourceWithOptions(scenario.uri, requestOptions),
629	      scenario.expect,
630	    );
631	    return;
632	  }
633	  if (scenario.kind === "resources.subscribe") {
634	    await client.subscribeResourceWithOptions(scenario.uri, requestOptions);
635	    return;
636	  }
637	  if (scenario.kind === "resources.unsubscribe") {
638	    await client.unsubscribeResourceWithOptions(scenario.uri, requestOptions);
639	    return;
640	  }
641	  if (scenario.kind === "prompts.get") {
642	    assertExpected(
643	      await client.getPromptWithOptions(scenario.prompt, scenario.arguments, requestOptions),
644	      scenario.expect,
645	    );
646	    return;
647	  }
648	  if (scenario.kind === "tools.call:task") {
649	    assertExpected(
650	      await client.createToolTaskWithOptions(
651	        scenario.tool,
652	        scenario.arguments,
653	        scenario.task,
654	        requestOptions,
655	      ),
656	      scenario.expect,
657	    );
658	    return;
659	  }
660	  if (scenario.kind === "tasks.get") {
661	    assertExpected(await client.getTaskWithOptions(scenario.taskId!, requestOptions), scenario.expect);
662	    return;
663	  }
664	  if (scenario.kind === "tasks.result") {
665	    assertExpected(
666	      await client.getTaskResultWithOptions(scenario.taskId!, requestOptions),
667	      scenario.expect,
668	    );
669	    return;
670	  }
671	  if (scenario.kind === "tasks.cancel") {
672	    assertExpected(
673	      await client.cancelTaskWithOptions(scenario.taskId!, requestOptions),
674	      scenario.expect,
675	    );
676	    return;
677	  }
678	  if (scenario.kind === "tasks.list") {
679	    assertExpected(
680	      await client.listTasksWithOptions(scenario.cursor, requestOptions),
681	      scenario.expect,
682	    );
683	    return;
684	  }
685	  if (scenario.kind === "events.expect") {
686	    const matching = observedEvents.filter((event) => event.kind === scenario.event);
687	    if (matching.length < (scenario.minimum ?? 1)) {
688	      throw new McpFnAssertionError(
689	        `Expected at least ${scenario.minimum ?? 1} ${scenario.event} event(s), received ${matching.length}`,
690	      );
691	    }
692	    if (scenario.expectPayload !== undefined) {
693	      assertExpected(matching.at(-1)?.payload, scenario.expectPayload);
694	    }
695	    return;
696	  }
697	  if (scenario.kind === "auth.assert") {
698	    if (!runOptions.auth) {
699	      throw new McpFnAssertionError("auth.assert requires a scenario auth adapter");
700	    }
701	    assertExpected(await runOptions.auth(scenario, requestOptions.signal), scenario.expect);
702	    return;
703	  }
704	  throw new McpFnAssertionError(`Unsupported scenario operation ${kind}`);
705	}
706	
707	function truncateError(value: string, options: McpFnScenarioRunOptions): string {
708	  const redacted = String(redactOAuthValue(value));
709	  const maxBytes = options.maxErrorBytes ?? 4_096;
710	  const bytes = new TextEncoder().encode(redacted);
711	  if (bytes.byteLength <= maxBytes) return redacted;
712	  return `${new TextDecoder().decode(bytes.slice(0, Math.max(0, maxBytes - 16)))}...[TRUNCATED]`;
713	}
714	
715	function defaultSideEffect(operation: string): "none" | "idempotent" | "non-idempotent" {
716	  return operation === "tools.call" || operation === "tools.call:task"
717	    ? "non-idempotent"
718	    : operation === "tasks.cancel"
719	      ? "idempotent"
720	      : "none";
721	}
722	
723	function assertExpected(actual: unknown, expected: unknown): void {
724	  if (expected !== undefined && stableJson(actual) !== stableJson(expected)) {
725	    throw new McpFnAssertionError(
726	      `Scenario result mismatch\nexpected: ${stableJson(expected)}\nactual:   ${stableJson(actual)}`,
727	    );
728	  }
729	}
730	
731	function isToolScenario(scenario: McpFnScenario): scenario is McpFnToolScenario {
732	  return "tool" in scenario;
733	}
734	
735	function isInventoryScenario(scenario: McpFnScenario): scenario is McpFnInventoryScenario {
736	  return ["tools.list", "resources.list", "resources.templates.list", "prompts.list"]
737	    .includes(scenario.kind ?? "");
738	}

