252	/** Validate an unknown scenario module before it reaches the shared runner. */
253	export function validateMcpFnScenarios(value: unknown): McpFnScenario[] {
254	  const scenarios = isScenarioArtifact(value) ? value.scenarios : value;
255	  if (!Array.isArray(scenarios)) {
256	    throw new Error("Scenario module must export an array or mcpfn.scenarios artifact");
257	  }
258	  for (const [index, scenario] of scenarios.entries()) {
259	    if (!scenario || typeof scenario !== "object" || Array.isArray(scenario)) {
260	      throw new Error(`Invalid scenario at index ${index}`);
261	    }
262	    const candidate = scenario as Record<string, unknown>;
263	    if (candidate.formatVersion !== undefined && candidate.formatVersion !== 1) {
264	      throw new Error(`Invalid scenario at index ${index}: unsupported formatVersion`);
265	    }
266	    if (typeof candidate.name !== "string" || !candidate.name.trim()) {
267	      throw new Error(`Invalid scenario at index ${index}: name is required`);
268	    }
269	    const kind = candidate.kind ?? "tools.call";
270	    const requiredField = kind === "tools.call" || kind === "tools.call:task"
271	      ? "tool"
272	      : kind === "resources.read" || kind === "resources.subscribe" ||
273	          kind === "resources.unsubscribe"
274	        ? "uri"
275	        : kind === "prompts.get"
276	          ? "prompt"
277	          : ["tasks.get", "tasks.result", "tasks.cancel"].includes(String(kind))
278	            ? "taskId"
279	            : kind === "events.expect"
280	              ? "event"
281	          : undefined;
282	    if (requiredField && typeof candidate[requiredField] !== "string") {
283	      throw new Error(
284	        `Invalid scenario at index ${index}: ${String(kind)} requires ${requiredField}`,
285	      );
286	    }
287	    if (!requiredField && ![
288	      "initialize",
289	      "tools.list",
290	      "resources.list",
291	      "resources.templates.list",
292	      "prompts.list",
293	      "tasks.list",
294	      "auth.assert",
295	    ].includes(String(kind))) {
296	      throw new Error(`Invalid scenario at index ${index}: unsupported kind ${String(kind)}`);
297	    }
298	    if (
299	      candidate.timeoutMs !== undefined &&
300	      (
301	        !Number.isInteger(candidate.timeoutMs) ||
302	        Number(candidate.timeoutMs) < 1 ||
303	        Number(candidate.timeoutMs) > 300_000
304	      )
305	    ) {
306	      throw new Error(`Invalid scenario at index ${index}: timeoutMs must be 1..300000`);
307	    }
308	    if (candidate.status === "incomplete" && typeof candidate.incompleteReason !== "string") {
309	      throw new Error(`Invalid scenario at index ${index}: incompleteReason is required`);
310	    }
311	    if (
312	      candidate.sideEffect !== undefined &&
313	      !["none", "idempotent", "non-idempotent"].includes(String(candidate.sideEffect))
314	    ) {
315	      throw new Error(`Invalid scenario at index ${index}: sideEffect is unsupported`);
316	    }
317	    if (
318	      candidate.variables !== undefined &&
319	      (
320	        !Array.isArray(candidate.variables) ||
321	        candidate.variables.some((entry) =>
322	          typeof entry !== "string" || !/^[A-Z][A-Z0-9_]*$/.test(entry)
323	        )
324	      )
325	    ) {
326	      throw new Error(`Invalid scenario at index ${index}: variables must be environment names`);
327	    }
328	    if (kind === "auth.assert") {
329	      const expectation = candidate.expect as Record<string, unknown> | undefined;
330	      if (
331	        typeof candidate.phase !== "string" ||
332	        !expectation ||
333	        !["allowed", "denied"].includes(String(expectation.outcome))
334	      ) {
335	        throw new Error(`Invalid scenario at index ${index}: auth.assert expectation is required`);
336	      }
337	    }
338	  }
339	  return scenarios as McpFnScenario[];
340	}
341	
342	export function createMcpFnScenarioArtifact(
343	  scenarios: McpFnScenario[],
344	  options: Omit<McpFnScenarioArtifact, "formatVersion" | "kind" | "scenarios"> = {
345	    status: "complete",
346	  },
347	): McpFnScenarioArtifact {
348	  return {
349	    formatVersion: 1,
350	    kind: "mcpfn.scenarios",
351	    ...options,
352	    scenarios: validateMcpFnScenarios(scenarios),
353	  };
354	}
355	
356	function isScenarioArtifact(value: unknown): value is McpFnScenarioArtifact {
357	  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
358	  const candidate = value as Record<string, unknown>;
359	  if (candidate.kind !== "mcpfn.scenarios") return false;
360	  if (candidate.formatVersion !== 1) {
361	    throw new Error("Unsupported McpFn scenario artifact formatVersion");
362	  }
363	  if (candidate.status !== "complete" && candidate.status !== "incomplete") {
364	    throw new Error("McpFn scenario artifact status must be complete or incomplete");
365	  }
366	  if (candidate.status === "incomplete" && typeof candidate.incompleteReason !== "string") {
367	    throw new Error("Incomplete McpFn scenario artifact requires incompleteReason");
368	  }
369	  return true;
370	}
371	
372	export async function runScenarios(
373	  client: McpFnTestClient<unknown>,
374	  scenarios: McpFnScenario[],
375	  options: McpFnScenarioRunOptions = {},
376	): Promise<McpFnScenarioResult[]> {
377	  if (
378	    options.defaultTimeoutMs !== undefined &&
379	    (
380	      !Number.isInteger(options.defaultTimeoutMs) ||
381	      options.defaultTimeoutMs < 1 ||
382	      options.defaultTimeoutMs > 300_000
383	    )
384	  ) {
385	    throw new Error("defaultTimeoutMs must be an integer from 1 through 300000");
386	  }
387	  if (
388	    options.maxScenarios !== undefined &&
389	    (!Number.isInteger(options.maxScenarios) || options.maxScenarios < 1)
390	  ) {
391	    throw new Error("maxScenarios must be a positive integer");
392	  }
393	  if (
394	    options.maxErrorBytes !== undefined &&
395	    (!Number.isInteger(options.maxErrorBytes) || options.maxErrorBytes < 64)
396	  ) {
397	    throw new Error("maxErrorBytes must be an integer of at least 64");
398	  }
399	  if (scenarios.length > (options.maxScenarios ?? 1_000)) {
400	    throw new Error(`Scenario count exceeds the configured cap of ${options.maxScenarios ?? 1_000}`);
401	  }
402	  const results: McpFnScenarioResult[] = [];
403	  const observedEvents: McpFnClientEvent[] = [];
404	  const unsubscribe = client.session.onEvent((event) => { observedEvents.push(event); });
405	  try {
406	    for (const scenario of scenarios) {
407	      const startedAt = performance.now();
408	      const operation = scenario.kind ?? "tools.call";
409	      const common = {
410	        formatVersion: 1 as const,
411	        name: scenario.name,
412	        operation,
413	        ...(isToolScenario(scenario) ? { tool: scenario.tool } : {}),
414	        sideEffect: scenario.sideEffect ?? defaultSideEffect(operation),
415	      };
416	      const resolved = resolveScenarioVariables(scenario, options.variables);
417	      if (resolved.missing.length > 0) {
418	        results.push({
419	          ...common,
420	          status: "incomplete",
421	          durationMs: 0,
422	          error: truncateError(
423	            `Missing scenario variables: ${resolved.missing.join(", ")}`,
424	            options,
425	          ),
426	        });
427	        continue;
428	      }
429	      if (scenario.status === "incomplete") {
430	        results.push({
431	          ...common,
432	          status: "incomplete",
433	          durationMs: 0,
434	          error: truncateError(scenario.incompleteReason ?? "Scenario is incomplete", options),
435	        });
436	        continue;
437	      }
438	      const timeoutMs = scenario.timeoutMs ?? options.defaultTimeoutMs ?? 30_000;
439	      const controller = new AbortController();
440	      let timer: ReturnType<typeof setTimeout> | undefined;
441	      try {
442	        await Promise.race([
443	          executeScenario(client, resolved.scenario, {
444	            signal: controller.signal,
445	            timeout: timeoutMs,
446	          }, observedEvents, options),
447	          new Promise<never>((_resolve, reject) => {
448	            timer = setTimeout(() => {
449	              controller.abort();
450	              reject(new McpFnAssertionError(`Scenario timed out after ${timeoutMs}ms`));
451	            }, timeoutMs);
452	            (timer as ReturnType<typeof setTimeout> & { unref?: () => void }).unref?.();
453	          }),
454	        ]);
455	        results.push({
456	          ...common,
457	          status: "passed",
458	          durationMs: performance.now() - startedAt,
459	        });
460	      } catch (error) {
461	        results.push({
462	          ...common,
463	          status: "failed",
464	          durationMs: performance.now() - startedAt,
465	          error: truncateError(error instanceof Error ? error.message : String(error), options),
466	        });
467	      } finally {
468	        if (timer) clearTimeout(timer);
469	      }
470	    }
471	  } finally {
472	    unsubscribe();
473	  }
474	  return results;
475	}
