707	function truncateError(value: string, options: McpFnScenarioRunOptions): string {
708	  const redacted = String(redactOAuthValue(value));
709	  const maxBytes = options.maxErrorBytes ?? 4_096;
710	  const bytes = new TextEncoder().encode(redacted);
711	  if (bytes.byteLength <= maxBytes) return redacted;
712	  return `${new TextDecoder().decode(bytes.slice(0, Math.max(0, maxBytes - 16)))}...[TRUNCATED]`;
713	}
714	
715	function defaultSideEffect(operation: string): "none" | "idempotent" | "non-idempotent" {
716	  return operation === "tools.call" || operation === "tools.call:task"
717	    ? "non-idempotent"
718	    : operation === "tasks.cancel"
719	      ? "idempotent"
720	      : "none";
721	}
722	
723	function assertExpected(actual: unknown, expected: unknown): void {
724	  if (expected !== undefined && stableJson(actual) !== stableJson(expected)) {
725	    throw new McpFnAssertionError(
726	      `Scenario result mismatch\nexpected: ${stableJson(expected)}\nactual:   ${stableJson(actual)}`,
727	    );
728	  }
729	}
