175	      expect: {
176	        isError: Boolean(toolResult.isError),
177	        ...(toolResult.structuredContent !== undefined
178	          ? { structuredContent: toolResult.structuredContent }
179	          : {}),
180	      },
181	    };
182	  }
183	  if (operation.kind === "tools.call:task") {
184	    return {
185	      formatVersion: 1,
