190	      ...(operation.arguments ? { arguments: operation.arguments } : {}),
191	      ...(operation.task ? { task: operation.task } : {}),
192	    };
193	  }
194	  if (operation.kind === "resources.read") {
195	    return {
196	      formatVersion: 1,
197	      name,
198	      kind: "resources.read",
199	      sideEffect: "none",
200	      uri: operation.uri,
201	      expect: result,
202	    };
203	  }
204	  if (operation.kind === "resources.subscribe" || operation.kind === "resources.unsubscribe") {
205	    return {
206	      formatVersion: 1,
207	      name,
208	      kind: operation.kind,
209	      sideEffect: "idempotent",
210	      uri: operation.uri,
211	    };
212	  }
213	  if (operation.kind === "tasks.get" || operation.kind === "tasks.cancel") {
214	    return {
215	      formatVersion: 1,
216	      name,
217	      kind: operation.kind,
