372	export async function runScenarios(
373	  client: McpFnTestClient<unknown>,
374	  scenarios: McpFnScenario[],
375	  options: McpFnScenarioRunOptions = {},
376	): Promise<McpFnScenarioResult[]> {
377	  if (
378	    options.defaultTimeoutMs !== undefined &&
379	    (
380	      !Number.isInteger(options.defaultTimeoutMs) ||
381	      options.defaultTimeoutMs < 1 ||
382	      options.defaultTimeoutMs > 300_000
383	    )
384	  ) {
385	    throw new Error("defaultTimeoutMs must be an integer from 1 through 300000");
386	  }
387	  if (
388	    options.maxScenarios !== undefined &&
389	    (!Number.isInteger(options.maxScenarios) || options.maxScenarios < 1)
390	  ) {
391	    throw new Error("maxScenarios must be a positive integer");
392	  }
393	  if (
394	    options.maxErrorBytes !== undefined &&
395	    (!Number.isInteger(options.maxErrorBytes) || options.maxErrorBytes < 64)
396	  ) {
397	    throw new Error("maxErrorBytes must be an integer of at least 64");
398	  }
399	  if (scenarios.length > (options.maxScenarios ?? 1_000)) {
400	    throw new Error(`Scenario count exceeds the configured cap of ${options.maxScenarios ?? 1_000}`);
401	  }
402	  const results: McpFnScenarioResult[] = [];
403	  const observedEvents: McpFnClientEvent[] = [];
404	  const unsubscribe = client.session.onEvent((event) => { observedEvents.push(event); });
405	  try {
406	    for (const scenario of scenarios) {
407	      const startedAt = performance.now();
408	      const operation = scenario.kind ?? "tools.call";
409	      const common = {
410	        formatVersion: 1 as const,
411	        name: scenario.name,
412	        operation,
413	        ...(isToolScenario(scenario) ? { tool: scenario.tool } : {}),
414	        sideEffect: scenario.sideEffect ?? defaultSideEffect(operation),
415	      };
416	      const resolved = resolveScenarioVariables(scenario, options.variables);
417	      if (resolved.missing.length > 0) {
418	        results.push({
419	          ...common,
420	          status: "incomplete",
421	          durationMs: 0,
422	          error: truncateError(
423	            `Missing scenario variables: ${resolved.missing.join(", ")}`,
424	            options,
425	          ),
426	        });
427	        continue;
428	      }
429	      if (scenario.status === "incomplete") {
430	        results.push({
431	          ...common,
432	          status: "incomplete",
433	          durationMs: 0,
434	          error: truncateError(scenario.incompleteReason ?? "Scenario is incomplete", options),
435	        });
436	        continue;
437	      }
438	      const timeoutMs = scenario.timeoutMs ?? options.defaultTimeoutMs ?? 30_000;
439	      const controller = new AbortController();
440	      let timer: ReturnType<typeof setTimeout> | undefined;
441	      try {
442	        await Promise.race([
443	          executeScenario(client, resolved.scenario, {
444	            signal: controller.signal,
445	            timeout: timeoutMs,
446	          }, observedEvents, options),
447	          new Promise<never>((_resolve, reject) => {
448	            timer = setTimeout(() => {
449	              controller.abort();
450	              reject(new McpFnAssertionError(`Scenario timed out after ${timeoutMs}ms`));
451	            }, timeoutMs);
452	            (timer as ReturnType<typeof setTimeout> & { unref?: () => void }).unref?.();
453	          }),
454	        ]);
455	        results.push({
456	          ...common,
457	          status: "passed",
458	          durationMs: performance.now() - startedAt,
459	        });
460	      } catch (error) {
461	        results.push({
462	          ...common,
463	          status: "failed",
464	          durationMs: performance.now() - startedAt,
465	          error: truncateError(error instanceof Error ? error.message : String(error), options),
466	        });
467	      } finally {
468	        if (timer) clearTimeout(timer);
469	      }
470	    }
471	  } finally {
472	    unsubscribe();
473	  }
474	  return results;
475	}
476	
477	export interface McpFnScenarioRunOptions {
478	  defaultTimeoutMs?: number;
479	  maxScenarios?: number;
480	  maxErrorBytes?: number;
481	  variables?: Record<string, string | undefined>;
482	  auth?(scenario: McpFnAuthScenario, signal: AbortSignal): Promise<{
483	    outcome: "allowed" | "denied";
484	    code?: string;
485	  }>;
486	}
487	
488	function resolveScenarioVariables(
489	  scenario: McpFnScenario,
490	  supplied: Record<string, string | undefined> | undefined,
491	): { scenario: McpFnScenario; missing: string[] } {
492	  const values = { ...process.env, ...supplied };
493	  const required = new Set(scenario.variables ?? []);
494	  const marker = /\$\{([A-Z][A-Z0-9_]*)\}/g;
495	  const visit = (value: unknown): unknown => {
496	    if (typeof value === "string") {
497	      for (const match of value.matchAll(marker)) required.add(match[1]);
498	      return value.replace(marker, (original, name: string) => values[name] ?? original);
499	    }
500	    if (Array.isArray(value)) return value.map(visit);
501	    if (value && typeof value === "object") {
502	      return Object.fromEntries(
503	        Object.entries(value as Record<string, unknown>).map(([key, entry]) => [key, visit(entry)]),
504	      );
505	    }
506	    return value;
507	  };
508	  const resolved = visit(scenario) as McpFnScenario;
509	  return {
510	    scenario: resolved,
511	    missing: [...required].filter((name) => values[name] === undefined).sort(),
512	  };
513	}
514	
515	export function createMcpFnScenarioReport(
516	  results: McpFnScenarioResult[],
517	  options: { manifestHash?: string; maxBytes?: number } = {},
518	): McpFnScenarioReport {
519	  const failed = results.filter((result) => result.status === "failed").length;
520	  const incomplete = results.filter((result) => result.status === "incomplete").length;
521	  const report: McpFnScenarioReport = {
522	    formatVersion: 1,
523	    kind: "mcpfn.scenario-report",
524	    status: incomplete === 0 ? "complete" : "incomplete",
525	    ...(options.manifestHash ? { manifestHash: options.manifestHash } : {}),
526	    total: results.length,
527	    passed: results.length - failed - incomplete,
528	    failed,
529	    incomplete,
530	    droppedResults: 0,
531	    results: structuredClone(results),
532	  };
533	  const maxBytes = options.maxBytes ?? 1_048_576;
534	  if (!Number.isInteger(maxBytes) || maxBytes < 1_024) {
535	    throw new Error("maxBytes must be an integer of at least 1024");
536	  }
537	  if (serializedBytes(report) > maxBytes) {
538	    report.status = "incomplete";
539	    report.incompleteReason = "Report content exceeded maxBytes and was truncated";
540	  }
541	  while (serializedBytes(report) > maxBytes && report.results.length > 0) {
542	    report.results.pop();
543	    report.droppedResults += 1;
544	  }
545	  if (report.droppedResults > 0) {
546	    report.status = "incomplete";
547	  }
548	  if (serializedBytes(report) > maxBytes) {
