    if (!requested) {
      await this.emit("authorization-request", "failed", "MCPFN_REDIRECT_MISSING");
      throw new Error("MCP authorization request is missing redirect_uri");
    }
    try {
      const client = await this.store.getClientInformation();
      const registered = "redirect_uris" in (client ?? {}) &&
          Array.isArray((client as { redirect_uris?: unknown }).redirect_uris)
        ? (client as { redirect_uris: string[] }).redirect_uris
        : this.clientMetadata.redirect_uris;
      const match = matchMcpRedirectUri(requested, registered, this.options.redirectPolicy);
      await this.options.openAuthorization(authorizationUrl);
      await this.emit("authorization-request", "succeeded", undefined, {
        redirect: match,
        clientId: authorizationUrl.searchParams.get("client_id"),
      });
    } catch (error) {
      await this.emit("authorization-request", "failed", readCode(error), {
        redirectOrigin: safeOrigin(requested),
        message: error instanceof Error ? error.message : String(error),
      });
      throw error;
    }
  }

  saveCodeVerifier(value: string): Promise<void> {
    return this.store.setCodeVerifier(value);
  }

  async codeVerifier(): Promise<string> {
    const value = await this.store.getCodeVerifier();
    if (!value) throw new Error("No PKCE verifier is available for this MCP authorization session");
    return value;
  }

  async validateAuthorizationState(value: string | undefined): Promise<void> {
    const expected = await this.store.getState();
    if (!expected || !value || expected !== value) {
      await this.emit("authorization-callback", "failed", "MCPFN_STATE_MISMATCH");
      throw new Error("MCP authorization callback state does not match the pending session");
    }
    await this.store.clear("state");
    await this.emit("authorization-callback", "succeeded");
  }

  invalidateCredentials(scope: McpFnOAuthCredentialScope): Promise<void> {
    return this.store.clear(scope);
  }

  async invalidatePendingAuthorization(): Promise<void> {
    await Promise.all([
      this.store.clear("verifier"),
      this.store.clear("state"),
    ]);
  }

  async revoke(): Promise<void> {
    const tokens = await this.store.getTokens();
    if (!tokens) {
      await this.emit("token-revocation", "succeeded", "MCPFN_NO_LOCAL_TOKEN", {
        remote: false,
      });
      return;
    }
    await this.emit("token-revocation", "started");
    try {
      if (!this.options.revoke) {
        const error = Object.assign(
          new Error("Remote token revocation is not configured; local credentials were retained"),
          { code: "MCPFN_REVOCATION_UNAVAILABLE" },
        );
        throw error;
      }
      await this.options.revoke(tokens);
      await this.store.clear("tokens");
      await this.emit("token-revocation", "succeeded");
    } catch (error) {
      await this.emit("token-revocation", "failed", readCode(error), {
        message: error instanceof Error ? error.message : String(error),
      });
      throw error;
    }
  }

  private async emit(
    phase: McpFnOAuthClientPhase,
    outcome: McpFnOAuthClientDiagnostic["outcome"],
    code?: string,
    details?: Record<string, unknown>,
  ): Promise<void> {
    try {
      await this.options.diagnostics?.(redactOAuthValue({
        phase,
        outcome,
        ...(code ? { code } : {}),
        at: (this.options.clock?.() ?? new Date()).toISOString(),
        ...(details ? { details } : {}),
      }));
    } catch {
      // Diagnostics are observational and must never change OAuth semantics.
    }
  }
}

export function createMcpFnOAuthClientProvider(
  options: McpFnOAuthClientProviderOptions,
): McpFnOAuthClientProvider {
  return new McpFnOAuthClientProvider(options);
}

function readCode(error: unknown): string | undefined {
  if (!error || typeof error !== "object") return undefined;
  const value = (error as { code?: unknown }).code;
  return typeof value === "string" || typeof value === "number" ? String(value) : undefined;
}

function safeOrigin(value: string): string {
  try {
    return new URL(value).origin;
  } catch {
    return "invalid";
  }
}

REDIRECTS
export interface McpFnRedirectPolicy {
  allowDynamicLoopbackPort?: boolean;
  allowLocalhostLoopback?: boolean;
  allowPrivateUseSchemes?: boolean;
}

export interface McpFnRedirectMatch {
  requested: string;
  registered: string;
  kind: "exact" | "loopback-dynamic-port";
}

export class McpFnRedirectMismatchError extends Error {
  readonly code = "MCPFN_REDIRECT_MISMATCH";
  readonly requested: string;

  constructor(requested: string) {
    super("The authorization redirect URI is not registered for this MCP client");
    this.name = "McpFnRedirectMismatchError";
    this.requested = redactRedirect(requested);
  }
}

/** Exact matching, except an explicitly enabled RFC 8252 loopback port. */
export function matchMcpRedirectUri(
  requested: string | URL,
  registeredRedirectUris: ReadonlyArray<string | URL>,
  policy: McpFnRedirectPolicy = {},
): McpFnRedirectMatch {
  const actual = new URL(requested.toString());
  if (
    !["http:", "https:"].includes(actual.protocol) &&
    policy.allowPrivateUseSchemes !== true
  ) {
    throw new McpFnRedirectMismatchError(actual.toString());
  }
  for (const candidateValue of registeredRedirectUris) {
    const candidate = new URL(candidateValue.toString());
    if (candidate.toString() === actual.toString()) {
      return {
        requested: actual.toString(),
        registered: candidate.toString(),
        kind: "exact",
      };
    }
    if (
      policy.allowDynamicLoopbackPort !== false &&
      isLoopback(actual, policy) &&
      isLoopback(candidate, policy) &&
      candidate.port === "" &&
      actual.port !== "" &&
      equalExceptPort(actual, candidate)
    ) {
      return {
        requested: actual.toString(),
        registered: candidate.toString(),
        kind: "loopback-dynamic-port",
      };
    }
  }
  throw new McpFnRedirectMismatchError(actual.toString());
}

function isLoopback(url: URL, policy: McpFnRedirectPolicy): boolean {
  if (url.protocol !== "http:") return false;
  const hostname = url.hostname.toLowerCase();
  return hostname === "127.0.0.1" ||
    hostname === "[::1]" ||
    (policy.allowLocalhostLoopback === true && hostname === "localhost");
}

function equalExceptPort(left: URL, right: URL): boolean {
  return left.protocol === right.protocol &&
    left.hostname.toLowerCase() === right.hostname.toLowerCase() &&
    left.pathname === right.pathname &&
    left.search === right.search &&
    left.hash === right.hash &&
    left.username === right.username &&
    left.password === right.password;
}

function redactRedirect(value: string): string {
  const url = new URL(value);
  url.search = url.search ? "?redacted" : "";
  url.hash = "";
  return url.toString();
}

PROVIDER
import type { AuthInfo } from "@modelcontextprotocol/sdk/server/auth/types.js";
import type { HandleRequestOptions } from "@modelcontextprotocol/sdk/server/webStandardStreamableHttp.js";

import { bearerChallengeResponse, readBearerToken } from "./auth-response.js";
import {
  protectedResourceMetadataUrl,
  type McpFnWebStandardHandler,
} from "./resource-server.js";

export interface McpFnPrincipal {
  subject: string;
  clientId: string;
  scopes: string[];
  resourceIds: string[];
  expiresAt?: number;
  tenantId?: string;
  regionId?: string;
  authMethods?: string[];
  extra?: Record<string, unknown>;
}

/** Structural subset implemented by AuthFn and other authentication providers. */
export interface McpFnAuthSessionLike {
  id: string;
  type: string;
  subject: {
    actorId: string;
    actorType: string;
    tenantId?: string;
    regionId?: string;
  };
  resourceIds?: string[];
  scopes?: string[];
  methods?: string[];
  expiresAt?: Date;
  metadata?: unknown;
}

/** AuthFn is optional: consumers can pass any provider matching this contract. */
export interface McpFnAuthProviderLike<TSession extends McpFnAuthSessionLike> {
  authenticate(request: Request): Promise<TSession | null>;
  authorize?(session: TSession, resourceId: string): Promise<boolean>;
  revoke?(sessionId: string): Promise<void>;
}

export interface McpFnAuthProviderAdapterOptions<TSession extends McpFnAuthSessionLike> {
  provider: McpFnAuthProviderLike<TSession>;
  resource: string | URL;
  map?(session: TSession, request: Request): McpFnPrincipal | Promise<McpFnPrincipal>;
  authorize?(input: {
    principal: McpFnPrincipal;
    request: Request;
  }): boolean | Promise<boolean>;
}

export interface McpFnAuthProviderAdapter<TSession extends McpFnAuthSessionLike> {
  authenticate(request: Request): Promise<{
    session: TSession;
    principal: McpFnPrincipal;
    authInfo: AuthInfo;
  } | null>;
}

export function createMcpFnAuthProviderAdapter<TSession extends McpFnAuthSessionLike>(
  options: McpFnAuthProviderAdapterOptions<TSession>,
): McpFnAuthProviderAdapter<TSession> {
  const resource = new URL(options.resource.toString());
  resource.hash = "";
  return {
    async authenticate(request) {
      const bearer = readBearerToken(request);
      if (!bearer) return null;
      const session = await options.provider.authenticate(request);
      if (!session) return null;
      const principal = options.map
        ? await options.map(session, request)
        : defaultPrincipal(session);
      if (
        options.provider.authorize &&
        !(await options.provider.authorize(session, resource.toString()))
      ) {
        return null;
      }
      if (options.authorize && !(await options.authorize({ principal, request }))) {
        return null;
      }
      return {
        session,
        principal,
        authInfo: {
          token: bearer,
          clientId: principal.clientId,
          scopes: [...principal.scopes],
          ...(principal.expiresAt !== undefined ? { expiresAt: principal.expiresAt } : {}),
          resource,
          extra: {
            ...principal.extra,
            subject: principal.subject,
            resourceIds: [...principal.resourceIds],
            ...(principal.tenantId ? { tenantId: principal.tenantId } : {}),
            ...(principal.regionId ? { regionId: principal.regionId } : {}),
            ...(principal.authMethods ? { authMethods: [...principal.authMethods] } : {}),
          },
        },
      };
    },
  };
}

export function createAuthProviderMcpHandler<TSession extends McpFnAuthSessionLike>(
  mcpHandler: McpFnWebStandardHandler,
  options: McpFnAuthProviderAdapterOptions<TSession>,
): (request: Request) => Promise<Response> {
  const adapter = createMcpFnAuthProviderAdapter(options);
  const metadataUrl = protectedResourceMetadataUrl(options.resource);
  return async (request) => {
    let authenticated;
    try {
      authenticated = await adapter.authenticate(request.clone());
    } catch {
      authenticated = null;
    }
    if (!authenticated) {
      return bearerChallengeResponse(401, metadataUrl, {
        error: "invalid_token",
        description: "A valid Bearer access token is required",
      });
    }
    const handleOptions: HandleRequestOptions = { authInfo: authenticated.authInfo };
    return mcpHandler(request, handleOptions);
  };
}

function defaultPrincipal(session: McpFnAuthSessionLike): McpFnPrincipal {
  return {
    subject: session.subject.actorId,
    clientId: session.id,
    scopes: [...(session.scopes ?? [])],
    resourceIds: [...(session.resourceIds ?? [])],
    ...(session.expiresAt
      ? { expiresAt: Math.floor(session.expiresAt.getTime() / 1_000) }
      : {}),
    ...(session.subject.tenantId ? { tenantId: session.subject.tenantId } : {}),
    ...(session.subject.regionId ? { regionId: session.subject.regionId } : {}),
    ...(session.methods ? { authMethods: [...session.methods] } : {}),
  };
}

