  if (copy.hash.length > 1) {
    const fragment = copy.hash.slice(1);
    const parameters = new URLSearchParams(fragment);
    let changed = false;
    for (const key of [...parameters.keys()]) {
      if (!isSensitiveUrlKey(key)) continue;
      parameters.set(key, REDACTED);
      changed = true;
