   931	async function readBoundedText(
   932	  source: Request | Response,
   933	  maxBytes: number,
   934	  signal?: AbortSignal,
   935	): Promise<string> {
   936	  if (!source.body) return "";
   937	  const reader = source.body.getReader();
   938	  const chunks: Uint8Array[] = [];
   939	  let total = 0;
   940	  const onAbort = () => {
   941	    void reader.cancel(new DOMException("aborted", "AbortError")).catch(() => undefined);
   942	  };
   943	  signal?.addEventListener("abort", onAbort, { once: true });
   944	  try {
   945	    if (signal?.aborted) throw new DOMException("aborted", "AbortError");
   946	    while (true) {
   947	      const { done, value } = await reader.read();
   948	      if (signal?.aborted) throw new DOMException("aborted", "AbortError");
   949	      if (done) break;
   950	      total += value.byteLength;
   951	      if (total > maxBytes) {
   952	        await reader.cancel().catch(() => undefined);
   953	        throw new McpFnHostedAuthorizationError("invalid_request", "Request body is too large", {
   954	          status: 413,
   955	        });
   956	      }
   957	      chunks.push(value);
   958	    }
   959	  } finally {
   960	    signal?.removeEventListener("abort", onAbort);
   961	    reader.releaseLock();
   962	  }
   963	  const bytes = new Uint8Array(total);
   964	  let offset = 0;
   965	  for (const chunk of chunks) {
   966	    bytes.set(chunk, offset);
   967	    offset += chunk.byteLength;
   968	  }
   969	  return new TextDecoder().decode(bytes);
   970	}
