   972	function withAbort<T>(promise: Promise<T>, signal: AbortSignal): Promise<T> {
   973	  if (signal.aborted) return Promise.reject(new DOMException("aborted", "AbortError"));
   974	  return new Promise<T>((resolve, reject) => {
   975	    const onAbort = () => {
   976	      cleanup();
   977	      reject(new DOMException("aborted", "AbortError"));
   978	    };
   979	    const cleanup = () => signal.removeEventListener("abort", onAbort);
   980	    signal.addEventListener("abort", onAbort, { once: true });
   981	    promise.then(
   982	      (value) => {
   983	        cleanup();
   984	        resolve(value);
   985	      },
   986	      (error) => {
   987	        cleanup();
   988	        reject(error);
   989	      },
   990	    );

