   152	    clientId: input.clientId,
   153	    source: input.source,
   154	    redirectUris,
   155	    responseTypes,
   156	    grantTypes,
   157	    tokenEndpointAuthMethod: input.metadata.token_endpoint_auth_method ?? "none",
   158	    metadata: {
   159	      ...input.metadata,
   160	      redirect_uris: redirectUris,
   161	      response_types: responseTypes,
   162	      grant_types: grantTypes,
   163	      token_endpoint_auth_method: input.metadata.token_endpoint_auth_method ?? "none",
   164	    },
