   168	export function validateMcpAuthorizationRequest(options: {
   169	  url: string | URL;
   170	  client: McpFnNormalizedClientRegistration;
   171	  redirectPolicy?: McpFnRedirectPolicy;
   172	  allowedResources?: ReadonlyArray<string | URL>;
   173	  supportedScopes?: ReadonlyArray<string>;
   174	}): McpFnValidatedAuthorizationRequest {
   175	  const url = new URL(options.url.toString());
   176	  const responseType = url.searchParams.get("response_type");
   177	  if (responseType !== "code" || !options.client.responseTypes.includes("code")) {
   178	    throw new McpFnHostedAuthorizationError(
   179	      "unsupported_response_type",
   180	      "This MCP authorization profile requires response_type=code",
   181	    );
   182	  }
   183	  if (!options.client.grantTypes.includes("authorization_code")) {
   184	    throw new McpFnHostedAuthorizationError(
   185	      "unauthorized_client",
   186	      "The client has no compatible authorization_code flow",
   187	    );
   188	  }
   189	  const requestedClientId = url.searchParams.get("client_id");
   190	  if (requestedClientId !== options.client.clientId) {
   191	    throw new McpFnHostedAuthorizationError("invalid_client", "client_id does not match registration");
   192	  }
   193	  const redirectUri = url.searchParams.get("redirect_uri");
   194	  if (!redirectUri) {
   195	    throw new McpFnHostedAuthorizationError("invalid_request", "redirect_uri is required");
   196	  }
   197	  let redirectMatch;
   198	  try {
   199	    redirectMatch = matchMcpRedirectUri(
   200	      redirectUri,
   201	      options.client.redirectUris,
   202	      options.redirectPolicy,
   203	    );
   204	  } catch (error) {
   205	    if (error instanceof McpFnRedirectMismatchError) {
   206	      throw new McpFnHostedAuthorizationError(
   207	        "invalid_request",
   208	        error.message,
   209	        { details: { phase: "redirect-validation", redirect: error.requested } },
   210	      );
   211	    }
   212	    throw error;
   213	  }
   214	  const codeChallenge = url.searchParams.get("code_challenge");
   215	  if (!codeChallenge) {
   216	    throw new McpFnHostedAuthorizationError("invalid_request", "PKCE code_challenge is required");
   217	  }
   218	  if (url.searchParams.get("code_challenge_method") !== "S256") {
   219	    throw new McpFnHostedAuthorizationError(
   220	      "invalid_request",
   221	      "PKCE code_challenge_method must be S256",
   222	    );
   223	  }
   224	  const resource = url.searchParams.get("resource") ?? undefined;
   225	  if (resource && options.allowedResources?.length) {
   226	    const allowed = new Set(options.allowedResources.map((value) => new URL(value.toString()).toString()));
   227	    if (!allowed.has(new URL(resource).toString())) {
   228	      throw new McpFnHostedAuthorizationError("invalid_target", "resource is not allowed");
   229	    }
   230	  }
   231	  const scopes = unique((url.searchParams.get("scope") ?? "").split(/\s+/).filter(Boolean));
   232	  if (options.supportedScopes) {
   233	    const supported = new Set(options.supportedScopes);
   234	    const unsupported = scopes.filter((scope) => !supported.has(scope));
   235	    if (unsupported.length) {
   236	      throw new McpFnHostedAuthorizationError("invalid_scope", "Requested MCP scope is unsupported", {
   237	        details: { unsupportedScopes: unsupported },
   238	      });
   239	    }
   240	  }
   280	    code?: string;
   281	    details?: Record<string, unknown>;
   282	  }): void | Promise<void>;
   283	}
