   289	export function createMcpAuthorizationCompatibilityHandler(
   290	  options: McpFnAuthorizationCompatibilityOptions,
   291	): (request: Request) => Promise<Response> {
   292	  validateClientMetadataDocumentOptions(options.clientMetadataDocuments);
   293	  const issuer = new URL(options.issuer.toString());
   294	  issuer.hash = "";
   295	  const endpoint = (path: string) => new URL(path, issuer).toString();
   296	  const tokenEndpointAuthMethods = unique(
   297	    options.capabilities?.tokenEndpointAuthMethods ?? ["none"],
   298	  ) as McpFnHostedTokenEndpointAuthMethod[];
   299	  validateHostedCapabilities(options, tokenEndpointAuthMethods);
   300	  const grantTypes = [
   301	    "authorization_code",
   302	    ...(options.tokenAuthority.refreshToken ? ["refresh_token"] : []),
   303	  ];
   304	  const metadata = {
   305	    ...options.extraMetadata,
   306	    issuer: issuer.toString(),
   307	    authorization_endpoint: endpoint("/authorize"),
   308	    token_endpoint: endpoint("/token"),
   309	    ...(options.clients.register ? { registration_endpoint: endpoint("/register") } : {}),
   310	    ...(options.tokenAuthority.revokeToken ? { revocation_endpoint: endpoint("/revoke") } : {}),
   311	    response_types_supported: ["code"],
   312	    grant_types_supported: grantTypes,
   313	    code_challenge_methods_supported: ["S256"],
   314	    token_endpoint_auth_methods_supported: tokenEndpointAuthMethods,
   315	    ...(options.supportedScopes ? { scopes_supported: unique(options.supportedScopes) } : {}),
   316	    client_id_metadata_document_supported: options.clientMetadataDocuments?.enabled === true,
   317	  };
   318	
   319	  return async (request): Promise<Response> => {
   320	    const url = new URL(request.url);
   321	    try {
   322	      if (
   323	        request.method === "GET" &&
   324	        (url.pathname === "/.well-known/oauth-authorization-server" ||
   325	          url.pathname === "/.well-known/openid-configuration")
   326	      ) {
   327	        return json(200, metadata, { "cache-control": "public, max-age=300" });
   328	      }
   329	      if (request.method === "POST" && url.pathname === "/register") {
   330	        if (!options.clients.register) {
   331	          throw new McpFnHostedAuthorizationError(
   332	            "invalid_request",
   333	            "Dynamic client registration is disabled",
   334	            { status: 404 },
   335	          );
   336	        }
   337	        const raw = await readBoundedJson(request, 256_000) as OAuthClientMetadata;
   338	        const metadata = normalizeClientMetadata(raw);
   339	        const registration = await options.clients.register(metadata, request);
   340	        await emit(options, "client-registration", "succeeded", undefined, {
   341	          clientId: registration.clientId,
   342	          source: registration.source,
   343	        });
   344	        return json(201, {
   345	          ...registration.metadata,
   346	          client_id: registration.clientId,
   347	        });
   348	      }
   349	      if (request.method === "GET" && url.pathname === "/authorize") {
   350	        const clientId = url.searchParams.get("client_id");
   351	        if (!clientId) {
   352	          throw new McpFnHostedAuthorizationError("invalid_request", "client_id is required");
   353	        }
   354	        const client = await resolveClient(options, clientId);
   355	        if (!client) {
   356	          throw new McpFnHostedAuthorizationError("invalid_client", "Unknown MCP client");
   357	        }
   358	        const validated = validateMcpAuthorizationRequest({
   359	          url,
   360	          client,
   361	          redirectPolicy: options.redirectPolicy,
   362	          allowedResources: options.allowedResources,
   363	          supportedScopes: options.supportedScopes,
   364	        });
   365	        if ((options.capabilities?.requireState ?? true) && !validated.state) {
   366	          throw new McpFnHostedAuthorizationError(
   367	            "invalid_request",
   368	            "state is required for this MCP authorization profile",
   369	          );
   370	        }
   371	        if (
   372	          (options.capabilities?.requireResource ?? Boolean(options.allowedResources?.length)) &&
   373	          !validated.resource
   374	        ) {
   375	          throw new McpFnHostedAuthorizationError(
   376	            "invalid_target",
   377	            "resource is required for this MCP authorization profile",
   378	          );
   379	        }
   380	        await emit(options, "authorization-request", "succeeded", undefined, {
   381	          clientId,
   382	          registrationSource: client.source,
   383	          redirectMatch: validated.redirectMatch,
   384	        });
   385	        return options.authorize(validated, request);
   386	      }
   387	      if (request.method === "POST" && url.pathname === "/token") {
   388	        return await handleTokenRequest(options, request, tokenEndpointAuthMethods);
   389	      }
   390	      if (
   391	        request.method === "POST" &&
   392	        url.pathname === "/revoke" &&
   393	        options.tokenAuthority.revokeToken
   394	      ) {
   395	        return await handleRevocationRequest(options, request, tokenEndpointAuthMethods);
   396	      }
   397	      return json(404, { error: "not_found" });
   398	    } catch (error) {
   399	      const normalized = error instanceof McpFnHostedAuthorizationError
   400	        ? error
   401	        : new McpFnHostedAuthorizationError(
   402	          "server_error",
   403	          "MCP authorization compatibility processing failed",
   404	          { status: 500 },
   405	        );
   406	      await emit(options, inferPhase(url.pathname), "failed", normalized.code, {
   407	        message: normalized.message,
   408	        ...normalized.details,
   409	      });
   410	      return json(normalized.status, {
   411	        error: normalized.code,
   412	        error_description: normalized.message,
   413	      });
   414	    }
   415	  };
   416	}
